englishA2Plans[81]={"title": "Reclamando de um serviço ruim", "file": "", "grammar": "Past simple regular e irregular em relatos", "goal": "Conte o que aconteceu usando o passado simples.", "words": [["complaint", "reclamação"], ["supervisor", "supervisor"], ["voucher", "vale"], ["make a fuss", "fazer escândalo"], ["charge", "cobrança"], ["rude", "grosseiro"], ["angry", "bravo"], ["upset", "chateado"], ["mistake", "erro"]]};
englishA2Content[81]=[[["Lia is a new tenant, and her landlord took her to dinner on Friday.", "Lia é uma nova inquilina, e o senhorio a levou para jantar na sexta."], ["They waited an hour, and the soup was cold.", "Eles esperaram uma hora, e a sopa estava fria."], ["Then the waiter made a mistake, and there was an extra charge on the bill.", "Aí o garçom cometeu um erro, e havia uma cobrança extra na conta."], ["Lia was upset, but she did not make a fuss.", "Lia ficou chateada, mas não fez escândalo."], ["She asked for the supervisor and made a complaint.", "Ela pediu o supervisor e fez uma reclamação."], ["The supervisor said sorry and gave her a voucher.", "O supervisor pediu desculpas e deu a ela um vale."]], [["Excuse me. Are you the supervisor? I have a complaint.", "Com licença. Você é o supervisor? Tenho uma reclamação."], ["Yes, I am. I'm sorry about the problem. What happened?", "Sim, sou. Sinto muito pelo problema. O que aconteceu?"], ["My landlord took me here after I signed the lease. We waited an hour, and the soup was cold.", "Meu senhorio me trouxe aqui depois que eu assinei o contrato. Esperamos uma hora, e a sopa estava fria."], ["Really? That's not good. The room is full tonight, but that's no excuse. Was he rude?", "Sério? Isso não é bom. O salão está cheio hoje, mas isso não é desculpa. Ele foi grosseiro?"], ["No, he wasn't rude. But he made a mistake on the bill, and there's an extra charge.", "Não, ele não foi grosseiro. Mas ele errou na conta, e tem uma cobrança extra."], ["Oh, I see it. You paid twenty dollars too much.", "Ah, estou vendo. Você pagou vinte dólares a mais."], ["I don't want to make a fuss. I'm not angry, but I'm upset.", "Não quero fazer escândalo. Não estou brava, mas estou chateada."], ["You're right. Here's your refund, and a voucher for your next dinner.", "Você tem razão. Aqui está o seu reembolso e um vale para o seu próximo jantar."]], ["/r/ em refund e manager", "Em refund e room, a língua não encosta em lugar nenhum: curve a ponta para trás e arredonde um pouco os lábios. Não faça o R forte do português, como em rato.", ["refund", "room"]], ["Lia ___ for the supervisor last night.", "asked", "asks", "Lia pediu o supervisor ontem à noite.", "Last night indica um momento no passado, então usamos o passado simples: asked."], [["They waited an hour, and the soup was cold.", "Eles esperaram uma hora, e a sopa estava fria."], ["Then the waiter made a mistake, and there was an extra charge on the bill.", "Aí o garçom cometeu um erro, e havia uma cobrança extra na conta."]], [{"t": "c", "q": "Yesterday the waiter ___ a mistake.", "o": ["made", "make", "makes"], "pt": "Ontem o garçom cometeu um erro.", "why": "Yesterday pede o passado simples, e o passado irregular de make é made."}, {"t": "l", "say": "We waited an hour for the bill.", "o": ["We waited an hour for the bill.", "We wait an hour for the bill.", "We waited an hour for the soup."], "why": "Waited está no passado, e o que esperaram foi a conta."}, {"t": "b", "pt": "O supervisor me deu um vale.", "w": ["The", "supervisor", "gave", "me", "a", "voucher"]}, {"t": "b", "pt": "Nós esperamos uma hora ontem.", "w": ["We", "waited", "an", "hour", "yesterday"]}]];
