englishA2Plans[82]={"title": "Primeira semana de intercâmbio", "file": "", "grammar": "Present perfect afirmativo (have + particípio regular)", "goal": "Diga o que você já fez usando have + particípio.", "words": [["exchange student", "intercambista"], ["dorm", "alojamento"], ["campus", "campus"], ["settle in", "se adaptar"], ["roommate", "colega de quarto"], ["cafeteria", "refeitório"], ["homesick", "com saudade de casa"], ["lost", "perdido"], ["professor", "professor"]]};
englishA2Content[82]=[[["Ben is an exchange student from Brazil.", "Ben é um intercambista do Brasil."], ["He has lived in the dorm for one week.", "Ele mora no alojamento há uma semana."], ["He has visited the campus and the cafeteria.", "Ele visitou o campus e o refeitório."], ["His roommate has helped him with the map.", "O colega de quarto o ajudou com o mapa."], ["Sometimes Ben feels homesick and a little lost.", "Às vezes Ben sente saudade de casa e fica um pouco perdido."], ["But he has started to settle in.", "Mas ele começou a se adaptar."]], [["Hi, Ben! How is your first week on campus?", "Oi, Ben! Como está sua primeira semana no campus?"], ["Pretty good. I've visited the library and the cafeteria.", "Bem boa. Eu visitei a biblioteca e o refeitório."], ["Nice. Do you like your roommate?", "Legal. Você gosta do seu colega de quarto?"], ["Yes, Tom is friendly. He has helped me a lot, and I have no complaint.", "Sim, o Tom é simpático. Ele me ajudou muito, e eu não tenho nenhuma reclamação."], ["Good. Are you homesick? I was homesick too, but I didn't make a fuss.", "Que bom. Você está com saudade de casa? Eu também fiquei, mas não fiz escândalo."], ["A little. I miss my family, but I've talked to them every day.", "Um pouco. Sinto falta da minha família, mas eu falei com eles todo dia."], ["That's good. Here, take this voucher for the cafeteria. My professor gave it to me.", "Que bom. Tome este vale para o refeitório. Meu professor me deu."], ["Thanks, Mia! I think I'm starting to settle in.", "Obrigado, Mia! Acho que estou começando a me adaptar."]], ["/æ/ em campus e exchange", "Em campus e exchange, abra bem a boca e leve a língua para a frente, num som entre o é e o a do português. Não diga campos com o A fechado.", ["campus", "exchange"]], ["Ben ___ in the dorm for one week.", "has lived", "lived", "Ben mora no alojamento há uma semana.", "For one week mostra algo que começou no passado e continua, então usamos has + particípio."], [["He has lived in the dorm for one week.", "Ele mora no alojamento há uma semana."], ["He has visited the campus and the cafeteria.", "Ele visitou o campus e o refeitório."]], [{"t": "c", "q": "I ___ the campus this week.", "o": ["have visited", "has visited", "visiting"], "pt": "Eu visitei o campus esta semana.", "why": "Com I usamos have + particípio: have visited."}, {"t": "l", "say": "Tom has helped me a lot.", "o": ["Tom has helped me a lot.", "Tom has helped him a lot.", "Tom helps me a lot."], "why": "A frase tem has helped e o objeto me."}, {"t": "b", "pt": "Eu moro no alojamento há uma semana.", "w": ["I've", "lived", "in", "the", "dorm", "for", "a", "week"]}, {"t": "b", "pt": "Ela ajudou a colega de quarto.", "w": ["She", "has", "helped", "her", "roommate"]}]];
