englishA2Plans[92]={"title": "Primeiro dia no novo emprego", "file": "", "grammar": "Present perfect com since", "goal": "Diga desde quando algo acontece usando since.", "words": [["lanyard", "cordão de crachá"], ["coworker", "colega de trabalho"], ["orientation", "orientação"], ["show someone around", "mostrar o lugar a alguém"], ["handbook", "manual"], ["paperwork", "papelada"], ["intern", "estagiário"], ["greet", "cumprimentar"], ["shift", "turno"]]};
englishA2Content[92]=[[["Today is Noah's first day at his new job.", "Hoje é o primeiro dia do Noah no novo emprego."], ["He has worn his lanyard and badge since eight o'clock.", "Ele usa o cordão e o crachá desde as oito horas."], ["A friendly coworker, Rosa, greets him at the door.", "Uma colega simpática, a Rosa, o cumprimenta na porta."], ["She has worked here since March.", "Ela trabalha aqui desde março."], ["She shows him around the office.", "Ela mostra o escritório a ele."], ["Noah has felt nervous since breakfast, but now he smiles.", "Noah está nervoso desde o café da manhã, mas agora ele sorri."]], [["Hi, I'm Noah. Today is my first day at the new job.", "Oi, sou o Noah. Hoje é meu primeiro dia no novo emprego."], ["Welcome, Noah! I'm Rosa. Orientation starts at nine.", "Bem-vindo, Noah! Sou a Rosa. A orientação começa às nove."], ["Great. Where is my cubicle? I have a handbook and some paperwork.", "Ótimo. Onde fica minha baia? Tenho um manual e alguma papelada."], ["Your cubicle is next to the photocopier. I can show you around first.", "Sua baia fica ao lado da fotocopiadora. Posso mostrar o lugar a você primeiro."], ["Thanks! Have you worked here for a long time?", "Obrigado! Você trabalha aqui há muito tempo?"], ["Yes, I've been on this team since March. Before that, I was in sales.", "Sim, estou nesta equipe desde março. Antes disso, eu estava em vendas."], ["Nice. An intern is going to help me, and my first shift starts tomorrow.", "Legal. Um estagiário vai me ajudar, e meu primeiro turno começa amanhã."], ["Right. Later, we can drop by the kiosk for coffee.", "Isso. Mais tarde, podemos dar uma passada no quiosque para um café."]], ["/dʒ/ em badge e manager", "Em badge e job, o som /dʒ/ começa com a língua no céu da boca e solta com voz, como o \"dj\" de \"djembê\". Não é o \"j\" suave do português.", ["badge", "job"]], ["Rosa has worked here ___ March.", "since", "for", "Rosa trabalha aqui desde março.", "Usamos since com um ponto no tempo, como March."], [["She has worked here since March.", "Ela trabalha aqui desde março."], ["Yes, I've been on this team since March. Before that, I was in sales.", "Sim, estou nesta equipe desde março. Antes disso, eu estava em vendas."]], [{"t": "c", "q": "I have had this badge ___ Monday.", "o": ["since", "for", "ago"], "pt": "Tenho este crachá desde segunda-feira.", "why": "Monday é um ponto no tempo, então usamos since."}, {"t": "l", "say": "He has been nervous since breakfast.", "o": ["He has been nervous since breakfast.", "He has been nervous for breakfast.", "He is nervous since breakfast."], "why": "Since + ponto no tempo, com have/has + been."}, {"t": "b", "pt": "Eu trabalho aqui desde junho.", "w": ["I", "have", "worked", "here", "since", "June"]}, {"t": "b", "pt": "Ela está nesta equipe desde março.", "w": ["She", "has", "been", "on", "this", "team", "since", "March"]}]];
