englishA2Plans[94]={"title": "Coleta de alimentos na igreja", "file": "", "grammar": "Perguntas com How long have you...?", "goal": "Pergunte há quanto tempo alguém faz algo.", "words": [["canned food", "comida enlatada"], ["pantry", "despensa"], ["charity", "entidade beneficente"], ["pitch in", "ajudar com a sua parte"], ["flyer", "panfleto"], ["collect", "recolher"], ["deliver", "entregar"], ["pasta", "macarrão"], ["stack", "empilhar"]]};
englishA2Content[94]=[[["Eva volunteers at her church every Saturday.", "Eva é voluntária na igreja dela todo sábado."], ["The church has a food drive this month.", "A igreja tem uma campanha de alimentos neste mês."], ["People bring canned food to the pantry.", "As pessoas trazem comida enlatada para a despensa."], ["Dan stacks the pasta on a long shelf.", "Dan empilha o macarrão em uma prateleira comprida."], ["Eva has collected five boxes of donations.", "Eva recolheu cinco caixas de doações."], ["Everyone pitches in for the charity.", "Todo mundo ajuda com a sua parte para a entidade beneficente."]], [["Hi, Dan. How long have you volunteered at this church?", "Oi, Dan. Há quanto tempo você é voluntário nesta igreja?"], ["For about two years. How long have you been here, Eva?", "Há uns dois anos. E você, Eva, há quanto tempo está aqui?"], ["Since January. I drop by every Saturday.", "Desde janeiro. Eu dou uma passada todo sábado."], ["Nice. We're going to deliver these flyers to the neighbors today.", "Legal. Vamos entregar estes panfletos aos vizinhos hoje."], ["Good idea. I brought a brochure from the charity too.", "Boa ideia. Trouxe também um folheto da entidade."], ["Thanks. Can you stack the pasta boxes? The heavy ones are hard for me.", "Obrigado. Você pode empilhar as caixas de macarrão? As pesadas são difíceis para mim."], ["Sure. Everyone should pitch in today.", "Claro. Todo mundo deveria ajudar hoje."], ["Exactly. Let's collect all the canned food first.", "Exato. Vamos recolher toda a comida enlatada primeiro."]], ["/tʃ/ em charity e pitch", "Em charity e church, o /tʃ/ é o \"tch\" de \"tchau\": a língua encosta no céu da boca e solta um pequeno estouro de ar, sem voz.", ["charity", "church"]], ["How long ___ you lived in this city?", "have", "did", "Há quanto tempo você mora nesta cidade?", "How long + have you + particípio pergunta há quanto tempo algo dura até agora."], [["Hi, Dan. How long have you volunteered at this church?", "Oi, Dan. Há quanto tempo você é voluntário nesta igreja?"], ["For about two years. How long have you been here, Eva?", "Há uns dois anos. E você, Eva, há quanto tempo está aqui?"]], [{"t": "c", "q": "How long ___ she worked at the pantry?", "o": ["has", "have", "did"], "pt": "Há quanto tempo ela trabalha na despensa?", "why": "Com she usamos has: How long has she + particípio."}, {"t": "l", "say": "How long have you volunteered here?", "o": ["How long have you volunteered here?", "How long do you volunteered here?", "How long have you volunteer here?"], "why": "A pergunta usa have you + particípio (volunteered)."}, {"t": "b", "pt": "Há quanto tempo você mora aqui?", "w": ["How", "long", "have", "you", "lived", "here"]}, {"t": "b", "pt": "Há quanto tempo ela ajuda a igreja?", "w": ["How", "long", "has", "she", "helped", "the", "church"]}]];
