englishA2Plans[97]={"title": "Um blecaute na cidade", "file": "", "grammar": "Past continuous negativo e perguntas", "goal": "Pergunte e responda sobre o que se fazia na hora.", "words": [["blackout", "apagão"], ["glow stick", "bastão luminoso"], ["outage", "falta de energia"], ["generator", "gerador"], ["fuse", "fusível"], ["dark", "escuro"], ["scared", "com medo"], ["melt", "derreter"], ["spoil", "estragar"]]};
englishA2Content[97]=[[["Last night, Nora was cooking dinner at eight o'clock.", "Ontem à noite, Nora estava cozinhando o jantar às oito horas."], ["Suddenly, there was a blackout in the whole street.", "De repente, houve um apagão na rua inteira."], ["It was dark, and Carl wasn't watching TV anymore.", "Estava escuro, e Carl não estava mais assistindo TV."], ["They weren't scared, so they took out two glow sticks.", "Eles não estavam com medo, então pegaram dois bastões luminosos."], ["The ice cream in the fridge was starting to melt.", "O sorvete na geladeira estava começando a derreter."], ["Then a gentle neighbor checked the fuse and started his generator.", "Então um vizinho gentil verificou o fusível e ligou seu gerador."]], [["Carl, the outage last night was long! Where were you?", "Carl, a falta de energia ontem à noite foi longa! Onde você estava?"], ["I was at home. I was cooking pasta when the lights went out.", "Eu estava em casa. Estava cozinhando macarrão quando a luz acabou."], ["Oh no! Weren't you scared in the dark?", "Ah, não! Você não ficou com medo no escuro?"], ["Not really. I had two glow sticks. What were you doing?", "Nem tanto. Eu tinha dois bastões luminosos. E você, o que estava fazendo?"], ["I was at the office with my coworker. The generator started after ten minutes.", "Eu estava no escritório com meu colega de trabalho. O gerador ligou depois de dez minutos."], ["Lucky you! My ice cream began to melt, and the milk could spoil.", "Que sorte! Meu sorvete começou a derreter, e o leite podia estragar."], ["But you have canned food in the pantry, right?", "Mas você tem comida enlatada na despensa, certo?"], ["Yes, we do. We ate canned soup by candlelight, and it was fun.", "Tenho, sim. Comemos sopa enlatada à luz de velas, e foi divertido."]], ["/dʒ/ em generator e jump", "Em generator e gentle, o \"g\" soa como /dʒ/, igual ao \"dj\" de \"djembê\". Comece com a língua no céu da boca e solte o som com voz.", ["generator", "gentle"]], ["I ___ watching TV when the power went out.", "wasn't", "didn't", "Eu não estava assistindo TV quando a luz acabou.", "Para negar uma ação em andamento no passado, usamos wasn't/weren't + verbo com -ing."], [["I was at home. I was cooking pasta when the lights went out.", "Eu estava em casa. Estava cozinhando macarrão quando a luz acabou."], ["Not really. I had two glow sticks. What were you doing?", "Nem tanto. Eu tinha dois bastões luminosos. E você, o que estava fazendo?"]], [{"t": "c", "q": "___ you sleeping at ten o'clock?", "o": ["Were", "Was", "Did"], "pt": "Você estava dormindo às dez horas?", "why": "Com you usamos Were + verbo com -ing na pergunta."}, {"t": "l", "say": "Was she cooking dinner?", "o": ["Was she cooking dinner?", "Does she cooking dinner?", "Was she cook dinner?"], "why": "Pergunta no past continuous: Was + sujeito + verbo com -ing."}, {"t": "b", "pt": "O que você estava fazendo?", "w": ["What", "were", "you", "doing"]}, {"t": "b", "pt": "Nós não estávamos assistindo TV.", "w": ["We", "weren't", "watching", "TV"]}]];
englishA2PhotoThemes[97]="city";
englishA2Plans[98]={"title": "Testemunha de um acidente leve", "file": "", "grammar": "Past continuous com while", "goal": "Una duas ações em andamento com while.", "words": [["witness", "testemunha"], ["bumper", "para-choque"], ["crossing", "faixa de pedestre"], ["pull over", "encostar o carro"], ["pedestrian", "pedestre"], ["honk", "buzinar"], ["dent", "amassado"], ["scratch", "arranhão"], ["insurance", "seguro"]]};
englishA2Content[98]=[[["Zoe was standing at the crossing near the railway.", "Zoe estava parada na faixa de pedestre perto da ferrovia."], ["While she was standing there, a red car was backing up.", "Enquanto ela estava parada ali, um carro vermelho estava dando ré."], ["A pedestrian was walking behind it, so the driver stopped.", "Um pedestre estava andando atrás dele, então o motorista parou."], ["The truck driver was honking while the car touched his bumper.", "O motorista do caminhão estava buzinando enquanto o carro tocava no para-choque dele."], ["There was a scratch on the truck and a dent on the car.", "Havia um arranhão no caminhão e um amassado no carro."], ["Zoe was the only witness.", "Zoe era a única testemunha."]], [["Thanks for waiting, ma'am. You're the witness, right?", "Obrigado por esperar, senhora. A senhora é a testemunha, certo?"], ["Yes. I saw everything from the crossing near the railway.", "Sim. Vi tudo da faixa de pedestre perto da ferrovia."], ["Good. The lights were dark after the outage, right? What was the red car doing?", "Bom. Os semáforos estavam apagados depois da falta de energia, certo? O que o carro vermelho estava fazendo?"], ["While I was waiting, the red car was backing up.", "Enquanto eu esperava, o carro vermelho estava dando ré."], ["Was anyone walking behind it?", "Alguém estava andando atrás dele?"], ["Yes, a pedestrian in a marathon shirt was crossing while the truck driver was honking.", "Sim, um pedestre com camisa de maratona estava atravessando enquanto o motorista do caminhão buzinava."], ["I see. The red car has a dent, and the truck has a scratch. Did they pull over?", "Entendi. O carro vermelho tem um amassado, e o caminhão, um arranhão. Eles encostaram?"], ["Yes, they both did. They're going to call their insurance today.", "Sim, os dois encostaram. Eles vão ligar para o seguro hoje."]], ["/w/ em witness e while", "Em witness e while, os lábios ficam arredondados como em \"u\" e abrem rápido, sem encostar os dentes. Pense em \"uí\"; não coloque um \"g\" na frente.", ["witness", "while"]], ["I was waiting ___ the truck was honking.", "while", "during", "Eu estava esperando enquanto o caminhão buzinava.", "While liga duas ações que acontecem ao mesmo tempo; durante usa um substantivo, não uma frase."], [["While she was standing there, a red car was backing up.", "Enquanto ela estava parada ali, um carro vermelho estava dando ré."], ["While I was waiting, the red car was backing up.", "Enquanto eu esperava, o carro vermelho estava dando ré."]], [{"t": "c", "q": "The pedestrian was walking ___ the driver was talking.", "o": ["while", "during", "then"], "pt": "O pedestre estava andando enquanto o motorista falava.", "why": "While liga duas ações em andamento ao mesmo tempo."}, {"t": "l", "say": "I was waiting while she was driving.", "o": ["I was waiting while she was driving.", "I was waiting while she were driving.", "I was waiting while she was drive."], "why": "Com she usamos was, e o verbo leva -ing."}, {"t": "b", "pt": "Enquanto eu esperava, ele buzinava.", "w": ["While", "I", "was", "waiting", "he", "was", "honking"]}, {"t": "b", "pt": "Ela estava assistindo enquanto eles conversavam.", "w": ["She", "was", "watching", "while", "they", "were", "talking"]}]];
