englishA2Plans[99]={"title": "Revisão: Noite de tempestade", "file": "", "grammar": "Revisão: past continuous com while e passado simples", "goal": "Conte o que fazia quando a tempestade chegou.", "words": [["thunder", "trovão"], ["lightning", "raio"], ["umbrella stand", "porta-guarda-chuva"], ["take cover", "abrigar-se"], ["raincoat", "capa de chuva"], ["mud", "lama"], ["soaked", "encharcado"], ["cozy", "aconchegante"], ["shiver", "tremer de frio"]]};
englishA2Content[99]=[[["Last night, Nora was walking home from the park.", "Ontem à noite, Nora estava voltando a pé do parque."], ["Suddenly, thunder shook the sky.", "De repente, um trovão sacudiu o céu."], ["Lightning lit up the whole street.", "Um raio iluminou a rua inteira."], ["Nora ran to a small café to take cover.", "Nora correu para um café pequeno para se abrigar."], ["She left her wet umbrella in the umbrella stand.", "Ela deixou o guarda-chuva molhado no porta-guarda-chuva."], ["She was soaked, and she began to shiver.", "Ela estava encharcada e começou a tremer de frio."]], [["Hi! Can I wait here? I'm soaked, and I have mud on my raincoat.", "Oi! Posso esperar aqui? Estou encharcada e tenho lama na minha capa de chuva."], ["Of course. Come in and put your umbrella in the umbrella stand.", "Claro. Entre e coloque o guarda-chuva no porta-guarda-chuva."], ["Thanks. I was walking home from the park when the storm started.", "Obrigada. Eu estava voltando a pé do parque quando a tempestade começou."], ["Really? I was making coffee when I heard the thunder. It was so loud!", "Sério? Eu estava fazendo café quando ouvi o trovão. Foi tão alto!"], ["I think the whole town heard it. Is the power still on?", "Acho que a cidade inteira ouviu. A luz ainda está acesa?"], ["Not now. The blackout began ten minutes ago, but the generator works.", "Agora não. O apagão começou há dez minutos, mas o gerador funciona."], ["Great. A hot chocolate sounds cozy. Do you have one?", "Ótimo. Um chocolate quente parece aconchegante. Você tem?"], ["Sure! Each cup helps a charity, and I'm going to bring a blanket.", "Claro! Cada copo ajuda uma entidade beneficente, e vou trazer um cobertor."]], ["/θ/ em thunder e thing", "Em thunder e think, coloque a ponta da língua entre os dentes e solte o ar, sem voz. Não troque por /s/ nem por /f/.", ["thunder", "think"]], ["I was cooking ___ the lights went out.", "when", "while", "Eu estava cozinhando quando a luz acabou.", "When introduz a ação curta que interrompe; while é para ações longas ao mesmo tempo."], [["Thanks. I was walking home from the park when the storm started.", "Obrigada. Eu estava voltando a pé do parque quando a tempestade começou."], ["Really? I was making coffee when I heard the thunder. It was so loud!", "Sério? Eu estava fazendo café quando ouvi o trovão. Foi tão alto!"]], [{"t": "c", "q": "While we were waiting, it ___ to rain.", "o": ["began", "begin", "begins"], "pt": "Enquanto esperávamos, começou a chover.", "why": "A ação curta que interrompe fica no passado simples: began."}, {"t": "l", "say": "I was sleeping when the thunder started.", "o": ["I was sleeping when the thunder started.", "I was sleeping while the thunder started.", "I were sleeping when the thunder started."], "why": "Com I usamos was, e when liga a ação curta que interrompe."}, {"t": "b", "pt": "Eu estava andando quando o trovão começou.", "w": ["I", "was", "walking", "when", "the", "thunder", "started"]}, {"t": "b", "pt": "Ela se abrigou no café.", "w": ["She", "took", "cover", "in", "the", "café"]}]];
englishA2PhotoThemes[99]="flag";
englishA2MiniStories[99]=["A noite da tempestade", "Nora was walking home when the storm started.~Nora estava voltando a pé para casa quando a tempestade começou.|The rain was heavy, and the wind was strong.~A chuva estava forte, e o vento também.|Her umbrella broke, so she ran into a small café.~O guarda-chuva dela quebrou, então ela correu para um café pequeno.|The owner, Jack, was cleaning the tables.~O dono, Jack, estava limpando as mesas.|While Nora was drying her hair, the lights went out.~Enquanto Nora secava o cabelo, a luz acabou.|Jack found two candles and made her a cup of hot tea.~Jack achou duas velas e fez uma xícara de chá quente para ela.|They talked about the storm for an hour.~Eles conversaram sobre a tempestade por uma hora.|Then Jack looked at her raincoat and smiled.~Então Jack olhou para a capa de chuva dela e sorriu.|It was his! She took it from the café by mistake last week.~Era a dele! Ela a pegou no café por engano na semana passada.|Nora gave it back, and Jack gave her a free cake.~Nora devolveu, e Jack lhe deu um bolo de graça."];
englishA2Plans[100]={"title": "Alarme de incêndio no prédio", "file": "", "grammar": "Past continuous interrompido por passado simples (when)", "goal": "Conte o que fazia quando algo interrompeu.", "words": [["smoke detector", "detector de fumaça"], ["staircase", "escadaria"], ["extinguisher", "extintor"], ["emergency exit", "saída de emergência"], ["panic", "entrar em pânico"], ["escape", "escapar"], ["evacuate", "evacuar"], ["ceiling", "teto"], ["scream", "gritar"]]};
englishA2Content[100]=[[["I was cooking dinner when the smoke detector started to beep.", "Eu estava preparando o jantar quando o detector de fumaça começou a apitar."], ["I didn't panic, and I grabbed the extinguisher from the kitchen.", "Eu não entrei em pânico e peguei o extintor da cozinha."], ["My neighbors were walking down the staircase when I opened the door.", "Meus vizinhos estavam descendo a escadaria quando abri a porta."], ["A little boy was screaming on the stairs, but his mom stayed calm.", "Um menino estava gritando na escada, mas a mãe dele ficou calma."], ["Smoke was rising to the ceiling when the firefighters arrived.", "A fumaça estava subindo até o teto quando os bombeiros chegaram."], ["We escaped through the emergency exit, and nobody got hurt.", "Nós escapamos pela saída de emergência, e ninguém se machucou."]], [["Ana, what were you doing when the alarm rang last night?", "Ana, o que você estava fazendo quando o alarme tocou ontem à noite?"], ["I was taking a shower when I heard the smoke detector.", "Eu estava tomando banho quando ouvi o detector de fumaça."], ["Really? Did you panic?", "Sério? Você entrou em pânico?"], ["A little. I put on my jacket and ran to the stairs with my neighbors.", "Um pouco. Coloquei minha jaqueta e corri para a escada com meus vizinhos."], ["We had to evacuate the whole building at midnight, and the siren was very loud.", "Tivemos de evacuar o prédio inteiro à meia-noite, e a sirene estava muito alta."], ["Was it a real fire, or just a drill?", "Era um incêndio de verdade ou só um simulado?"], ["Just burnt popcorn on the third floor. A man was screaming at his microwave!", "Só pipoca queimada no terceiro andar. Um homem estava gritando com o micro-ondas!"], ["Ha! The blackout last month was worse, because the generator didn't start.", "Ha! O apagão do mês passado foi pior, porque o gerador não ligou."], ["I remember. Were you walking down the staircase when the lights went out?", "Eu me lembro. Você estava descendo a escadaria quando as luzes apagaram?"], ["Yes, I was. I held a glow stick all the way down.", "Sim, estava. Segurei um bastão luminoso o caminho todo."]], ["/s/ em staircase e stairs", "Comece com um 's' limpo, sem um 'e' na frente (não diga 'estairs'). O ar sai fino entre a língua e os dentes de cima; em staircase e stairs o 's' vem antes do 't'.", ["staircase", "stairs"]], ["We were eating dinner when the alarm ___.", "rang", "was ringing", "Nós estávamos jantando quando o alarme tocou.", "A ação curta que interrompe fica no passado simples; a ação longa usa o past continuous."], [["I was cooking dinner when the smoke detector started to beep.", "Eu estava preparando o jantar quando o detector de fumaça começou a apitar."], ["I was taking a shower when I heard the smoke detector.", "Eu estava tomando banho quando ouvi o detector de fumaça."]], [{"t": "c", "q": "Ben was reading when the lights ___.", "o": ["went out", "going out", "goes out"], "pt": "Ben estava lendo quando as luzes apagaram.", "why": "A ação curta que interrompe usa o passado simples: went out."}, {"t": "l", "say": "I was sleeping when the alarm rang.", "o": ["I was sleeping when the alarm rang.", "I was sleeping while the alarm rang.", "I slept when the alarm was ringing."], "why": "Você ouviu a ação longa (was sleeping) e a curta que interrompe (rang) ligadas por when."}, {"t": "b", "pt": "Eu estava cozinhando quando o detector apitou.", "w": ["I", "was", "cooking", "when", "the", "smoke", "detector", "beeped"]}, {"t": "b", "pt": "Eu estava na escada quando o alarme tocou.", "w": ["I", "was", "on", "the", "stairs", "when", "it", "rang"]}]];
