englishA2Plans[105]={"title": "Planos de férias na praia", "file": "", "grammar": "Will vs going to", "goal": "Diferencie decisão na hora de plano já feito.", "words": [["flip-flops", "chinelos"], ["pelican", "pelicano"], ["sandcastle", "castelo de areia"], ["pack your bags", "fazer as malas"], ["cooler", "caixa térmica"], ["snorkel", "snorkel, tubo de respiração"], ["tan", "bronzeado"], ["dive", "mergulhar"], ["sunburn", "queimadura de sol"]]};
englishA2Content[105]=[[["Lia and Noah are going to spend a week at the beach.", "Lia e Noah vão passar uma semana na praia."], ["Lia is going to buy sunscreen, because she doesn't want a sunburn.", "Lia vai comprar protetor solar, porque não quer se queimar."], ["Noah is going to bring a cooler with cold drinks.", "Noah vai levar uma caixa térmica com bebidas geladas."], ["At the beach, a lifeguard sits near the water.", "Na praia, um salva-vidas fica perto da água."], ["Noah wants a tan, so Lia says, \"I'll bring a hat for you.\"", "Noah quer um bronzeado, então Lia diz: \"Eu levo um chapéu para você.\""], ["The kids are going to build a sandcastle, and the adults are going to rest.", "As crianças vão construir um castelo de areia, e os adultos vão descansar."]], [["Noah, are you ready for the beach trip? You should pack your bags tonight.", "Noah, você está pronto para a viagem à praia? Você deve fazer as malas hoje à noite."], ["I'm going to pack after dinner. I already have my flip-flops and a hat.", "Vou fazer as malas depois do jantar. Já tenho meus chinelos e um chapéu."], ["Great. Oh no, I forgot the sunscreen! I'll buy some on the way.", "Ótimo. Ah, não, esqueci o protetor solar! Compro um no caminho."], ["Good idea. I want to bring a snorkel because I love to dive near the rocks.", "Boa ideia. Quero levar um snorkel porque adoro mergulhar perto das pedras."], ["Cool! The lifeguard says the water is clear, and a pelican lives there.", "Legal! O salva-vidas diz que a água está limpa, e um pelicano mora lá."], ["Wait, the hotel is calling me. Hold on, I'll answer it.", "Espere, o hotel está me ligando. Um momento, eu atendo."], ["Okay. Ask about the weather. Is there humidity, or just a nice breeze?", "Certo. Pergunte sobre o tempo. Tem umidade ou só uma brisa gostosa?"], ["They say it's sunny now, and the clouds clear up by noon.", "Eles dizem que está ensolarado agora, e as nuvens se dissipam até o meio-dia."], ["Perfect. I'm so excited! Did you bring a cooler for the drinks?", "Perfeito. Estou tão animada! Você trouxe uma caixa térmica para as bebidas?"], ["Yes, I did. It's in the car, and the sandcastle bucket is there too.", "Trouxe, sim. Está no carro, e o balde do castelo de areia também está lá."]], ["/aɪ/ em lifeguard e sunscreen", "O som /aɪ/ começa com a boca bem aberta, como em 'pai', e termina deslizando para o 'i'. Em lifeguard e sunscreen, diga 'láif' e 'sân-skrin', com um ditongo claro.", ["lifeguard", "sunscreen"]], ["The phone is ringing! I ___ answer it.", "will", "am going to", "O telefone está tocando! Eu atendo.", "Decisão na hora usa will; plano já feito usa be going to."], [["I'm going to pack after dinner. I already have my flip-flops and a hat.", "Vou fazer as malas depois do jantar. Já tenho meus chinelos e um chapéu."], ["Great. Oh no, I forgot the sunscreen! I'll buy some on the way.", "Ótimo. Ah, não, esqueci o protetor solar! Compro um no caminho."]], [{"t": "c", "q": "We bought the tickets last week. We ___ fly on Friday.", "o": ["are going to", "are go to", "goes to"], "pt": "Compramos as passagens semana passada. Vamos voar na sexta.", "why": "Plano já feito: be + going to + verbo."}, {"t": "l", "say": "I'll buy some sunscreen now.", "o": ["I'll buy some sunscreen now.", "I'm going to buy some sunscreen now.", "I'll buy some sunscreen later."], "why": "Você ouviu I'll (will) e now: uma decisão tomada na hora."}, {"t": "b", "pt": "Eu vou comprar protetor solar agora.", "w": ["I'll", "buy", "sunscreen", "right", "now"]}, {"t": "b", "pt": "Nós vamos fazer um castelo de areia.", "w": ["We", "are", "going", "to", "build", "a", "sandcastle"]}]];
