englishA2Plans[108]={"title": "Guarda de trânsito e a multa", "file": "", "grammar": "First conditional com if + will", "goal": "Diga o que acontecerá se algo ocorrer.", "words": [["fine", "multa"], ["speed limit", "limite de velocidade"], ["traffic cop", "guarda de trânsito"], ["pay up", "pagar o que deve"], ["license", "carteira de motorista"], ["warning", "advertência"], ["intersection", "cruzamento"], ["tow", "rebocar"]]};
englishA2Content[108]=[[["Ruth was driving near an intersection when a traffic cop stopped her.", "Ruth estava dirigindo perto de um cruzamento quando um guarda de trânsito a parou."], ["The speed limit there is 30 miles per hour, but she was going 45.", "O limite de velocidade ali é de 30 milhas por hora, mas ela estava a 45."], ["The cop checks her license and gives her a warning.", "O guarda confere a carteira dela e lhe dá uma advertência."], ["He says, \"If you drive fast again, you'll have to pay up.\"", "Ele diz: \"Se você dirigir rápido de novo, vai ter de pagar.\""], ["A pedestrian was crossing the street, and Ruth didn't see him.", "Um pedestre estava atravessando a rua, e Ruth não o viu."], ["Ruth says, \"I'm sorry. If I see a pedestrian, I'll stop next time.\"", "Ruth diz: \"Desculpe. Se eu vir um pedestre, vou parar da próxima vez.\""]], [["Ruth, why are you late? Did you have a parking problem?", "Ruth, por que você está atrasada? Teve problema com estacionamento?"], ["No, a traffic cop stopped me near the intersection. I was thinking about work.", "Não, um guarda de trânsito me parou perto do cruzamento. Eu estava pensando no trabalho."], ["Oh no. Did you get a fine?", "Ah, não. Você levou uma multa?"], ["Not this time. He gave me a warning. The speed limit was 30, and I was going 45.", "Desta vez não. Ele me deu uma advertência. O limite era 30, e eu estava a 45."], ["If you drive that fast again, you'll pay a big fine.", "Se você dirigir tão rápido de novo, vai pagar uma multa alta."], ["I know. I'll stick to the speed limit from now on. If I forget, you can tell me.", "Eu sei. Vou respeitar o limite de velocidade daqui para a frente. Se eu esquecer, você pode me avisar."], ["Deal. By the way, if we leave now, we'll get to the beach before noon.", "Combinado. A propósito, se sairmos agora, chegaremos à praia antes do meio-dia."], ["Sounds fun! I have the picnic basket in the trunk, and the trail map is here.", "Parece divertido! Tenho a cesta de piquenique no porta-malas, e o mapa da trilha está aqui."], ["Great. But look, a big car is blocking us, and the tow truck is coming!", "Ótimo. Mas olhe, um carro grande está bloqueando a saída, e o guincho está vindo!"], ["Don't worry, it's someone else's car. Yes, we can go now!", "Não se preocupe, é o carro de outra pessoa. Sim, podemos ir agora!"]], ["/ŋ/ em ticket e parking", "O /ŋ/ de parking e thinking é um 'n' feito no fundo da boca, com a língua atrás tocando o céu da boca, sem soltar um 'g' depois. Pense no 'n' de 'banco', mas sem o 'k'.", ["parking", "thinking"]], ["If you drive fast, you ___ pay a fine.", "will", "are", "Se você dirigir rápido, vai pagar uma multa.", "Na primeira condicional, if + presente simples traz a consequência com will."], [["If you drive that fast again, you'll pay a big fine.", "Se você dirigir tão rápido de novo, vai pagar uma multa alta."], ["Deal. By the way, if we leave now, we'll get to the beach before noon.", "Combinado. A propósito, se sairmos agora, chegaremos à praia antes do meio-dia."]], [{"t": "c", "q": "If you ___ the speed limit, you'll get a fine.", "o": ["break", "will break", "broke"], "pt": "Se você ultrapassar o limite de velocidade, vai levar uma multa.", "why": "Depois de if usamos o presente simples, não will."}, {"t": "l", "say": "If I see the cop, I'll slow down.", "o": ["If I see the cop, I'll slow down.", "If I will see the cop, I'll slow down.", "If I saw the cop, I'll slow down."], "why": "Depois de if vem o presente (see); will fica só na consequência."}, {"t": "b", "pt": "Se chover, nós vamos ficar em casa.", "w": ["If", "it", "rains", "we'll", "stay", "home"]}, {"t": "b", "pt": "Se você dirigir rápido, vai pagar uma multa.", "w": ["If", "you", "drive", "fast", "you'll", "pay", "a", "fine"]}]];
