englishA2Plans[109]={"title": "Revisão: Mudança de cidade", "file": "", "grammar": "Revisão: will, going to, used to e present perfect", "goal": "Fale do passado, presente e futuro da sua mudança.", "words": [["moving van", "caminhão de mudança"], ["cardboard box", "caixa de papelão"], ["bubble wrap", "plástico-bolha"], ["movers", "carregadores de mudança"], ["unpack", "desempacotar"], ["dolly", "carrinho de carga"], ["doorway", "vão da porta"], ["front door", "porta da frente"]]};
englishA2Content[109]=[[["Kate has lived in this city for ten years, but now she is moving.", "Kate mora nesta cidade há dez anos, mas agora está se mudando."], ["She is going to rent a small house near the beach.", "Ela vai alugar uma casa pequena perto da praia."], ["The movers have loaded the moving van with cardboard boxes.", "Os carregadores já carregaram o caminhão de mudança com caixas de papelão."], ["She used to hate packing, but she has wrapped everything in bubble wrap.", "Ela costumava odiar fazer malas, mas embrulhou tudo em plástico-bolha."], ["One box says \"fragile\", and the boy next door helps carry it.", "Uma caixa diz \"frágil\", e o menino da casa ao lado ajuda a carregá-la."], ["The dolly can't pass through the doorway, so Kate will unpack the boxes first.", "O carrinho não passa pela porta, então Kate vai desempacotar as caixas primeiro."]], [["Kate, have you finished packing yet? The movers are coming at nine.", "Kate, você já terminou de arrumar tudo? Os carregadores chegam às nove."], ["Almost. I've packed all the books, but I haven't wrapped the glasses yet.", "Quase. Já guardei todos os livros, mas ainda não embrulhei os copos."], ["Use the bubble wrap. I used to break a lot of glasses when I moved.", "Use o plástico-bolha. Eu costumava quebrar muitos copos quando me mudava."], ["Good idea. I'm going to put the picnic basket in the van, and the hammock too.", "Boa ideia. Vou colocar a cesta de piquenique no caminhão, e a rede também."], ["Don't forget the trail map. You'll want it near the new house.", "Não esqueça o mapa da trilha. Você vai querer perto da casa nova."], ["Right! The beach has great trails. I'll hike every Sunday, and it will be my new habit.", "Certo! A praia tem ótimas trilhas. Vou fazer trilha todo domingo, e vai ser meu novo hábito."], ["That sounds great. Have you ever lived near the sea before?", "Parece ótimo. Você já morou perto do mar antes?"], ["No, never. I'm a little nervous, and the noise of the waves will be new for me.", "Não, nunca. Estou um pouco nervosa, e o barulho das ondas vai ser novo para mim."], ["You'll love it. The streets are quiet, and the speed limit is low.", "Você vai adorar. As ruas são calmas, e o limite de velocidade é baixo."], ["Yes, it's a calm place, and I think I'm going to be happy there.", "Sim, é um lugar calmo, e acho que vou ser feliz lá."]], ["/ɔɪ/ em moving e noise", "O ditongo /ɔɪ/ começa com a boca arredondada, como o 'ó' de 'pó', e desliza para o 'i', como em 'boi'. Em noise e boy, diga 'nóiz' e 'bói'.", ["noise", "boy"]], ["Kate ___ lived in this city for ten years.", "has", "have", "Kate mora nesta cidade há dez anos.", "Com Kate (ela) usamos has + particípio no present perfect."], [["Kate has lived in this city for ten years, but now she is moving.", "Kate mora nesta cidade há dez anos, mas agora está se mudando."], ["Almost. I've packed all the books, but I haven't wrapped the glasses yet.", "Quase. Já guardei todos os livros, mas ainda não embrulhei os copos."]], [{"t": "c", "q": "We ___ packed all the cardboard boxes.", "o": ["have", "has", "are"], "pt": "Nós já arrumamos todas as caixas de papelão.", "why": "Com we usamos have + particípio no present perfect."}, {"t": "l", "say": "I'm going to rent a small house.", "o": ["I'm going to rent a small house.", "I used to rent a small house.", "I'll rent a small house."], "why": "Você ouviu I'm going to: um plano para o futuro."}, {"t": "b", "pt": "Eu costumava morar perto da praia.", "w": ["I", "used", "to", "live", "near", "the", "beach"]}, {"t": "b", "pt": "Eles ainda não desempacotaram as caixas.", "w": ["They", "haven't", "unpacked", "the", "boxes", "yet"]}]];
englishA2PhotoThemes[109]="city";
englishA2MiniStories[109]=["A caixa extra", "On moving day, Kate was tired, but the movers worked fast.~No dia da mudança, Kate estava cansada, mas os carregadores trabalharam rápido.|She counted the boxes and found one extra box.~Ela contou as caixas e achou uma caixa a mais.|The box said \"fragile\", but it wasn't her handwriting.~A caixa dizia \"frágil\", mas não era a letra dela.|The boy next door looked at it and laughed.~O menino da casa ao lado olhou para ela e riu.|He shouted, \"That's my box!\"~Ele gritou: \"Essa caixa é minha!\"|The movers put it in the wrong van by mistake.~Os carregadores a puseram no caminhão errado por engano.|Inside, there was an old guitar that he used to play every day.~Dentro, havia um violão velho que ele costumava tocar todos os dias.|Kate gave the box back, and he played a song for her.~Kate devolveu a caixa, e ele tocou uma música para ela.|The noise was loud, but Kate smiled.~O barulho era alto, mas Kate sorriu.|Now they are good friends, and they are going to share a picnic on Sunday.~Agora eles são bons amigos e vão fazer um piquenique juntos no domingo."];
englishA2ExtraWordExamples[109]={"front door": ["We haven't painted the front door yet.", "Ainda não pintamos a porta da frente."]};
englishA2Plans[110]={"title": "Um mês de treino para a corrida", "file": "", "grammar": "Present perfect continuous simples (have been + -ing)", "goal": "Diga o que vem fazendo ultimamente com have been -ing.", "words": [["stride", "passada"], ["stopwatch", "cronômetro"], ["sore muscle", "músculo dolorido"], ["keep it up", "continue assim"], ["pace", "ritmo"], ["ankle", "tornozelo"], ["shoelace", "cadarço"], ["running shoes", "tênis de corrida"]]};
englishA2Content[110]=[[["Ana has been running every morning for a month.", "A Ana corre todas as manhãs há um mês."], ["Her new sneakers are light, and her stopwatch is always in her pocket.", "Os tênis novos dela são leves, e o cronômetro está sempre no bolso."], ["At first, her stride was short and her pace was slow.", "No começo, a passada dela era curta e o ritmo era lento."], ["Now she stretches her ankle every day, so her sore muscles feel fine.", "Agora ela alonga o tornozelo todo dia, então os músculos doloridos estão bem."], ["Yesterday her shoelace came loose, so she stopped and tied it.", "Ontem o cadarço dela soltou, então ela parou e amarrou de novo."], ["Her coach smiled and said, “Nice stride, Ana! Keep it up!”", "O treinador dela sorriu e disse: “Boa passada, Ana! Continue assim!”"]], [["Ben, you look tired. What have you been doing?", "Ben, você parece cansado. O que você tem feito?"], ["I'm training for the city race, and my ankle hurts a little.", "Estou treinando para a corrida da cidade, e meu tornozelo dói um pouco."], ["Really? How long have you been running?", "Sério? Há quanto tempo você está correndo?"], ["I've been running every morning for three weeks, and I sweat a lot!", "Eu venho correndo toda manhã há três semanas, e suo muito!"], ["Wow! Do you use a stopwatch to check your pace?", "Uau! Você usa um cronômetro para ver seu ritmo?"], ["Yes, I do. Yesterday I got a cramp, so I stopped for a minute.", "Uso. Ontem tive uma câimbra, então parei por um minuto."], ["Don't worry. Sore muscles are normal when you start a new habit.", "Não se preocupe. Músculos doloridos são normais quando você começa um hábito novo."], ["Thanks, Ana. I'll keep it up, and I'll stick to my plan.", "Valeu, Ana. Vou continuar assim e vou seguir meu plano."]], ["/s/ em sneakers e stopwatch", "Em “sneakers” e “stopwatch” o /s/ é um sopro de ar entre os dentes, sem vibrar a garganta, como o “s” de “sapo”. Cuidado para não colocar um “i” antes do s (não diga “isneakers”).", ["sneakers", "stopwatch"]], ["Ana ___ running every morning for a month.", "has been", "have been", "A Ana corre todas as manhãs há um mês.", "Com Ana (she) usamos has been + verbo com -ing para uma ação que começou no passado e continua."], [["Ana has been running every morning for a month.", "A Ana corre todas as manhãs há um mês."], ["I've been running every morning for three weeks, and I sweat a lot!", "Eu venho correndo toda manhã há três semanas, e suo muito!"]], [{"t": "c", "q": "We ___ studying English since January.", "o": ["have been", "are", "were"], "pt": "Estamos estudando inglês desde janeiro.", "why": "Para uma ação que começou no passado e continua até agora, usamos have been + -ing com since."}, {"t": "l", "say": "I've been running every day.", "o": ["I've been running every day.", "I've been resting every day.", "I've been running every night."], "why": "Ouça o verbo (running) e o período (every day)."}, {"t": "b", "pt": "O Ben tem corrido todas as manhãs.", "w": ["Ben", "has", "been", "running", "every", "morning"]}, {"t": "b", "pt": "Há quanto tempo você está treinando?", "w": ["How", "long", "have", "you", "been", "training"]}]];
englishA2PhotoThemes[110]="map";
englishA2ExtraWordExamples[110]={"running shoes": ["I've been wearing these running shoes all month.", "Estou usando este tênis de corrida o mês todo."]};
englishA2Plans[111]={"title": "Aula de direção", "file": "", "grammar": "First conditional com unless e if not", "goal": "Dê avisos usando unless.", "words": [["learner", "aprendiz"], ["steering wheel", "volante"], ["gearshift", "câmbio"], ["roundabout", "rotatória"], ["crosswalk", "faixa de pedestres"], ["dashboard", "painel do carro"], ["reverse", "marcha à ré"], ["turn signal", "seta (do carro)"]]};
englishA2Content[111]=[[["Tom is a learner, and today is his first driving lesson.", "Tom é aprendiz, e hoje é a primeira aula de direção dele."], ["He holds the steering wheel with both hands.", "Ele segura o volante com as duas mãos."], ["“Don't touch the gearshift unless I tell you,” says the instructor.", "“Não toque no câmbio a menos que eu mande”, diz a instrutora."], ["At the crosswalk, Tom stops and waits for a pedestrian.", "Na faixa de pedestres, Tom para e espera um pedestre."], ["At the roundabout, he goes slowly and follows the speed limit.", "Na rotatória, ele vai devagar e respeita o limite de velocidade."], ["He won't get his license unless he practices, but today he did fine.", "Ele não vai tirar a carteira a menos que pratique, mas hoje ele foi bem."]], [["Tom, put on your seat belt. We won't start unless you're ready.", "Tom, coloque o cinto. Não vamos sair a menos que você esteja pronto."], ["I'm ready, Ms. Cruz. Why is that light on the dashboard?", "Estou pronto, Sra. Cruz. Por que aquela luz está acesa no painel?"], ["It's a warning light. It stays on unless the door is closed.", "É uma luz de aviso. Ela fica acesa a menos que a porta esteja fechada."], ["Oh, the door isn't closed! Sorry. Now I'm ready.", "Ah, a porta não está fechada! Desculpe. Agora estou pronto."], ["Good. Now turn slowly and stick to the speed limit. If you don't slow down, you'll miss the exit.", "Bom. Agora vire devagar e respeite o limite de velocidade. Se você não diminuir, vai perder a saída."], ["Can I use reverse here? I want to park near the curb.", "Posso usar a marcha à ré aqui? Quero estacionar perto da calçada."], ["Not yet. Look in the mirror first, and check for pedestrians.", "Ainda não. Olhe no espelho primeiro e veja se há pedestres."], ["Okay, I see one. I'll stop and wait here.", "Certo, estou vendo um. Vou parar e esperar aqui."]], ["/ɜr/ em learner e turn", "Em “learner” e “turn”, o som /ɜr/ sai com a língua puxada para trás, sem encostar no céu da boca, e o r fica preso na vogal. Não pronuncie “lérner” com um e seguido de um r bem separado.", ["learner", "turn"]], ["You can't drive ___ you have a license.", "unless", "if", "Você não pode dirigir a menos que tenha carteira.", "Unless significa “se não”: a proibição vale a menos que você tenha a carteira."], [["“Don't touch the gearshift unless I tell you,” says the instructor.", "“Não toque no câmbio a menos que eu mande”, diz a instrutora."], ["It's a warning light. It stays on unless the door is closed.", "É uma luz de aviso. Ela fica acesa a menos que a porta esteja fechada."]], [{"t": "c", "q": "We won't be late ___ the bus is slow.", "o": ["unless", "if", "when"], "pt": "Não vamos nos atrasar a menos que o ônibus esteja lento.", "why": "Unless significa “a menos que”: a única coisa que atrasa a gente é o ônibus lento."}, {"t": "l", "say": "Don't touch the gearshift unless I say so.", "o": ["Don't touch the gearshift unless I say so.", "Don't touch the gearshift until I say so.", "Don't touch the gearshift unless I see so."], "why": "Ouça a palavra unless e o final say so."}, {"t": "b", "pt": "Ela não vai sair a menos que pare de chover.", "w": ["She", "won't", "go", "out", "unless", "it", "stops", "raining"]}, {"t": "b", "pt": "Você vai se perder se não olhar o mapa.", "w": ["You", "will", "get", "lost", "if", "you", "don't", "look"]}]];
englishA2PhotoThemes[111]="notebook";
englishA2ExtraWordExamples[111]={"turn signal": ["Unless you use the turn signal, other drivers won't know.", "A menos que você use a seta, os outros motoristas não vão saber."]};
englishA2Plans[112]={"title": "Experiência no laboratório de química", "file": "", "grammar": "Zero conditional (if + presente, presente)", "goal": "Descreva fatos que sempre acontecem usando if.", "words": [["test tube", "tubo de ensaio"], ["lab coat", "jaleco"], ["chemical", "produto químico"], ["boil over", "transbordar ao ferver"], ["pour", "despejar"], ["spill", "derramar"], ["flask", "frasco de laboratório"], ["safety goggles", "óculos de proteção"]]};
englishA2Content[112]=[[["Noah puts on his lab coat and goggles, and Mia takes the stopwatch.", "Noah veste o jaleco e os óculos de proteção, e a Mia pega o cronômetro."], ["She pours a clear chemical into a test tube.", "Ela despeja um produto químico transparente em um tubo de ensaio."], ["“If you heat milk too fast, it boils over,” says Noah.", "“Se você esquenta o leite rápido demais, ele transborda”, diz Noah."], ["A little gas comes out of the flask.", "Um pouco de gás sai do frasco."], ["If ice gets warm, it melts, and the table gets wet.", "Se o gelo esquenta, ele derrete, e a mesa fica molhada."], ["Noah spills a drop, but Mia says, “It's fine. Clean it up.”", "Noah derrama uma gota, mas a Mia diz: “Tudo bem. Limpe.”"]], [["Noah, put on your goggles. This chemical can hurt your eyes.", "Noah, ponha os óculos de proteção. Este produto químico pode machucar seus olhos."], ["Okay. What happens if I mix these two liquids?", "Certo. O que acontece se eu misturar estes dois líquidos?"], ["If you mix them, they make gas, and the flask gets warm.", "Se você misturar, eles formam gás, e o frasco esquenta."], ["Sounds fun! Can I pour some into this test tube?", "Parece divertido! Posso despejar um pouco neste tubo de ensaio?"], ["Sure. Go slowly, and use the stopwatch to count the minutes.", "Claro. Vá devagar e use o cronômetro para contar os minutos."], ["Interesting. I know that water freezes if the temperature drops to zero.", "Interessante. Sei que a água congela se a temperatura cai a zero."], ["Right. Now put the cap on, and wash your hands.", "Certo. Agora ponha a tampa e lave as mãos."], ["Okay, Mia. Everything is fine, and I'm ready for the next test.", "Certo, Mia. Está tudo bem, e estou pronto para o próximo teste."]], ["/ɡ/ em goggles e gas", "O “g” de “goggles” e “gas” é igual ao “g” de “gato”: a parte de trás da língua toca o céu da boca e solta o ar com voz. Não confunda com o “j” de “gente”.", ["goggles", "gas"]], ["If you heat ice, it ___.", "melts", "melt", "Se você esquenta gelo, ele derrete.", "No zero conditional usamos o presente nos dois lados, e com it o verbo leva -s."], [["If you mix them, they make gas, and the flask gets warm.", "Se você misturar, eles formam gás, e o frasco esquenta."], ["If ice gets warm, it melts, and the table gets wet.", "Se o gelo esquenta, ele derrete, e a mesa fica molhada."]], [{"t": "c", "q": "If you ___ milk too fast, it boils over.", "o": ["heat", "will heat", "heated"], "pt": "Se você esquenta o leite rápido demais, ele transborda.", "why": "Num fato que sempre acontece, usamos o presente simples depois de if."}, {"t": "l", "say": "If I mix them, they make gas.", "o": ["If I mix them, they make gas.", "If I mixed them, they made gas.", "If I miss them, they make gas."], "why": "Ouça mix e o presente make."}, {"t": "b", "pt": "Se você esquenta o leite rápido, ele transborda.", "w": ["If", "you", "heat", "milk", "fast", "it", "boils", "over"]}, {"t": "b", "pt": "Ela usa óculos de proteção se mistura produtos químicos.", "w": ["She", "wears", "goggles", "if", "she", "mixes", "chemicals"]}]];
