englishA2ExtraWordExamples[112]={"boil over": ["Don't let the soup boil over.", "Não deixe a sopa transbordar."], "safety goggles": ["If you mix them, you need safety goggles.", "Se você misturar os dois, precisa de óculos de proteção."]};
englishA2Plans[113]={"title": "Esperando o ônibus escolar", "file": "", "grammar": "When e as soon as com futuro", "goal": "Fale de ações futuras usando when e as soon as.", "words": [["crossing guard", "guarda de trânsito escolar"], ["lunchbox", "lancheira"], ["shuttle", "ônibus de translado"], ["pick up", "buscar"], ["mittens", "luvas de lã"], ["stroller", "carrinho de bebê"], ["principal", "diretor(a)"], ["school bus", "ônibus escolar"]]};
englishA2Content[113]=[[["Rosa waits at the bus stop with her little brother in his stroller.", "A Rosa espera no ponto de ônibus com o irmãozinho no carrinho de bebê."], ["It's cold and rainy, so she wears a raincoat and mittens.", "Está frio e chovendo, então ela usa uma capa de chuva e luvas de lã."], ["The crossing guard stops the cars like a traffic cop.", "O guarda de trânsito escolar para os carros como um guarda de trânsito."], ["Rosa's lunchbox is in her backpack.", "A lancheira da Rosa está na mochila dela."], ["The yellow shuttle bus is on time, and the driver always follows the speed limit.", "O ônibus amarelo está no horário, e o motorista sempre respeita o limite de velocidade."], ["When the driver comes, he will pick up the kids at the corner.", "Quando o motorista chegar, ele vai buscar as crianças na esquina."]], [["Hi, Dan. Is the shuttle late today?", "Oi, Dan. O ônibus está atrasado hoje?"], ["A little, but it's fine. The crossing guard says it will be here in five minutes.", "Um pouco, mas tudo bem. A guarda diz que ele chega em cinco minutos."], ["I'm cold. When it comes, I'll sit near the heater.", "Estou com frio. Quando ele chegar, vou sentar perto do aquecedor."], ["Good idea. As soon as we get to school, I'm going to run to the cafeteria.", "Boa ideia. Assim que chegarmos à escola, vou correr para a cantina."], ["Me too. I forgot my lunchbox, so I'll buy lunch there.", "Eu também. Esqueci minha lancheira, então vou comprar o almoço lá."], ["No problem, I'll share my sandwich. Then I have to talk to the principal about the club.", "Sem problema, divido meu sanduíche. Depois tenho que falar com o diretor sobre o clube."], ["Thanks! Look, the bus is here. When the door opens, we'll run!", "Obrigada! Olha, o ônibus chegou. Quando a porta abrir, vamos correr!"], ["Don't run! Walk slowly, and I'll hold the door for you.", "Não corra! Ande devagar, e eu seguro a porta para você."]], ["/ʌ/ em shuttle e bus", "O “u” de “bus” e “shuttle” é uma vogal curta e relaxada, entre o “a” e o “é” do português, com a boca quase parada. Não diga “bús” com o “u” fechado do português.", ["shuttle", "bus"]], ["When the shuttle ___, we'll go to school.", "comes", "will come", "Quando o ônibus chegar, vamos para a escola.", "Depois de when usamos o presente simples, mesmo falando do futuro."], [["I'm cold. When it comes, I'll sit near the heater.", "Estou com frio. Quando ele chegar, vou sentar perto do aquecedor."], ["Good idea. As soon as we get to school, I'm going to run to the cafeteria.", "Boa ideia. Assim que chegarmos à escola, vou correr para a cantina."]], [{"t": "c", "q": "As soon as I ___ home, I'll call you.", "o": ["get", "will get", "got"], "pt": "Assim que eu chegar em casa, vou ligar para você.", "why": "Depois de as soon as usamos o presente simples, não will."}, {"t": "l", "say": "When the bus comes, I'll sit near you.", "o": ["When the bus comes, I'll sit near you.", "When the bus comes, I sat near you.", "When the bus will come, I'll sit near you."], "why": "Ouça comes (presente) e I'll sit (futuro)."}, {"t": "b", "pt": "Assim que eu chegar, vou ligar para você.", "w": ["As", "soon", "as", "I", "arrive", "I'll", "call", "you"]}, {"t": "b", "pt": "Quando o ônibus chegar, nós vamos entrar.", "w": ["When", "the", "bus", "comes", "we'll", "get", "on"]}]];
