englishA2ExtraWordExamples[113]={"school bus": ["When the school bus comes, the kids will get on.", "Quando o ônibus escolar chegar, as crianças vão embarcar."]};
englishA2Plans[114]={"title": "Um convite ainda incerto", "file": "", "grammar": "Might e may para possibilidade", "goal": "Fale de possibilidades usando might e may.", "words": [["rumor", "boato"], ["chance", "chance"], ["probably", "provavelmente"], ["fingers crossed", "torcendo para dar certo"], ["invite", "convidar"], ["decide", "decidir"], ["decorate", "decorar"], ["sleepover", "festa do pijama"]]};
englishA2Content[114]=[[["There's a rumor at school: Sam's family is moving.", "Há um boato na escola: a família do Sam vai se mudar."], ["Lia thinks they might have a goodbye party.", "A Lia acha que eles talvez façam uma festa de despedida."], ["A moving van is in front of Sam's house, and the movers carry cardboard boxes.", "Um caminhão de mudança está em frente à casa do Sam, e os carregadores levam caixas de papelão."], ["Lia wants to invite her friends and decorate the yard.", "A Lia quer convidar os amigos e decorar o quintal."], ["She will probably text Sam tonight.", "Ela provavelmente vai mandar mensagem para o Sam hoje à noite."], ["“Fingers crossed! We may have a chance to say goodbye,” she says.", "“Torcendo! Talvez a gente tenha uma chance de se despedir”, ela diz."]], [["Sam, is the rumor true? Is your family moving?", "Sam, o boato é verdade? Sua família vai se mudar?"], ["Yes, we are. The movers may come on Saturday.", "Sim, vamos. Os carregadores talvez venham no sábado."], ["Oh no! Are you going to have a party before you leave?", "Ah, não! Vocês vão fazer uma festa antes de ir?"], ["We might. My mom hasn't decided yet, and she's very busy.", "Talvez. Minha mãe ainda não decidiu, e ela está muito ocupada."], ["If it's a party, I'll bring cheese sandwiches. We'll need a lot of them.", "Se for uma festa, eu levo sanduíches de queijo. Vamos precisar de muitos."], ["Thanks! The old cardboard boxes might be our tables, ha!", "Valeu! As caixas de papelão velhas talvez sejam nossas mesas, ha!"], ["Ha! Text me when you know. A sleepover is a great idea, too!", "Ha! Me mande mensagem quando souber. Uma festa do pijama também é uma ótima ideia!"], ["I will. I'll text you tonight, and I'll invite the whole class.", "Mando sim. Mando mensagem hoje à noite e convido a turma toda."]], ["/tʃ/ em chance e cheese", "O “ch” de “chance” e “cheese” soa como o “tch” de “tchau”: a língua começa no céu da boca e solta o ar de uma vez. Não é o “x” suave de “xícara”.", ["chance", "cheese"]], ["I ___ go to the party, but I'm not sure.", "might", "must", "Eu talvez vá à festa, mas não tenho certeza.", "Might indica possibilidade; must seria obrigação e não combina com “não tenho certeza”."], [["Lia thinks they might have a goodbye party.", "A Lia acha que eles talvez façam uma festa de despedida."], ["Yes, we are. The movers may come on Saturday.", "Sim, vamos. Os carregadores talvez venham no sábado."]], [{"t": "c", "q": "Sam's family ___ move in June, but nobody knows.", "o": ["may", "must", "should"], "pt": "A família do Sam talvez se mude em junho, mas ninguém sabe.", "why": "May indica possibilidade; “ninguém sabe” mostra que não é certo."}, {"t": "l", "say": "She might come to the party.", "o": ["She might come to the party.", "She must come to the party.", "She might not come to the party."], "why": "Ouça might (possibilidade) e a ausência de not."}, {"t": "b", "pt": "Nós talvez tenhamos uma festa.", "w": ["We", "might", "have", "a", "party"]}, {"t": "b", "pt": "Ele talvez esteja em casa hoje à noite.", "w": ["He", "may", "be", "at", "home", "tonight"]}]];
englishA2PhotoThemes[114]="map";
englishA2Plans[115]={"title": "Pedindo licença em uma biblioteca universitária", "file": "", "grammar": "May I para pedir permissão", "goal": "Peça e dê permissão com May I.", "words": [["librarian", "bibliotecário"], ["study carrel", "cabine de estudo"], ["catalog", "catálogo"], ["due date", "data de devolução"], ["borrow", "pegar emprestado"], ["renew", "renovar"], ["overdue", "atrasado (devolução)"], ["whisper", "sussurrar"]]};
englishA2Content[115]=[[["Mia comes from the lab in her lab coat to find a book about chemicals.", "A Mia vem do laboratório de jaleco para achar um livro sobre produtos químicos."], ["The librarian shows her the catalog on the computer.", "O bibliotecário mostra o catálogo a ela no computador."], ["The book is on the top shelf, next to a stack of magazines.", "O livro está na prateleira de cima, ao lado de uma pilha de revistas."], ["Mia finds a study carrel and whispers to her friend.", "A Mia acha uma cabine de estudo e sussurra para a amiga."], ["She wants to borrow the book, and the due date is Friday.", "Ela quer pegar o livro emprestado, e a data de devolução é sexta."], ["Food isn't allowed, so her lunchbox stays in her bag.", "Comida não é permitida, então a lancheira dela fica na bolsa."]], [["Excuse me. May I ask you a question about the catalog?", "Com licença. Posso fazer uma pergunta sobre o catálogo?"], ["Of course. What are you looking for?", "Claro. O que você procura?"], ["A chemistry book. May I take it home for two weeks?", "Um livro de química. Posso levar para casa por duas semanas?"], ["Sure. You may keep it until the due date. Is it your first time here?", "Claro. Pode ficar com ele até a data de devolução. É a sua primeira vez aqui?"], ["Yes. Is it quiet in the study carrels? I forgot my headphones.", "Sim. É silencioso nas cabines de estudo? Esqueci meus fones."], ["It is, but please whisper. And your account has no overdue books, so you can borrow three.", "É, mas por favor sussurre. E sua conta não tem livros atrasados, então você pode pegar três."], ["Great! Can I renew it online if I need more time?", "Ótimo! Posso renovar on-line se precisar de mais tempo?"], ["Yes, you can renew it twice. Here's your card. Enjoy the book!", "Sim, pode renovar duas vezes. Aqui está seu cartão. Aproveite o livro!"]], ["/ʃ/ em shelf e librarian", "O “sh” de “shelf” e “show” é o “ch” do português em “chá”: lábios um pouco arredondados e ar contínuo, sem vibrar a garganta. Não troque por “s” (não diga “self”).", ["shelf", "show"]], ["___ I sit here?", "May", "Do", "Posso me sentar aqui?", "Para pedir permissão educadamente, usamos May I + verbo."], [["Excuse me. May I ask you a question about the catalog?", "Com licença. Posso fazer uma pergunta sobre o catálogo?"], ["A chemistry book. May I take it home for two weeks?", "Um livro de química. Posso levar para casa por duas semanas?"]], [{"t": "c", "q": "___ I borrow this book, please?", "o": ["May", "Do", "Am"], "pt": "Posso pegar este livro emprestado, por favor?", "why": "May I + verbo é a forma educada de pedir permissão."}, {"t": "l", "say": "May I use the study carrel?", "o": ["May I use the study carrel?", "May I see the study carrel?", "May I close the study carrel?"], "why": "Ouça o verbo depois de May I: use."}, {"t": "b", "pt": "Posso pegar este livro emprestado?", "w": ["May", "I", "borrow", "this", "book"]}, {"t": "b", "pt": "Você pode renovar o livro on-line.", "w": ["You", "may", "renew", "the", "book", "online"]}]];
