englishA2Plans[116]={"title": "Regras do aluguel de bicicletas", "file": "", "grammar": "Have to afirmativo", "goal": "Diga o que é obrigatório usando have to.", "words": [["kickstand", "descanso da bicicleta"], ["spokes", "raios da roda"], ["rental", "aluguel"], ["sign up", "inscrever-se"], ["rack", "bicicletário"], ["code", "código"], ["payment", "pagamento"], ["flat", "vazio (pneu)"]]};
englishA2Content[116]=[[["Ana and Noah want to ride bikes at the beach, so they go to the rental shop.", "Ana e Noah querem andar de bicicleta na praia, então vão à loja de aluguel."], ["First, they have to sign up and show an ID.", "Primeiro, eles têm que se inscrever e mostrar um documento."], ["Everyone has to wear a helmet, and it has to fit well.", "Todo mundo tem que usar capacete, e ele tem que servir bem."], ["The worker says, “You have to enter the code at the rack to open your bike.”", "O funcionário diz: “Vocês têm que digitar o código no bicicletário para abrir a bicicleta.”"], ["Noah checks the spokes and the kickstand, but one tire is flat.", "O Noah confere os raios e o descanso, mas um pneu está vazio."], ["Near the street, they have to wait for the crossing guard.", "Perto da rua, eles têm que esperar o guarda de trânsito."]], [["Noah, do we have to sign up before we take the bikes?", "Noah, a gente tem que se inscrever antes de pegar as bicicletas?"], ["Yes, we do. We have to give our names and make the payment here.", "Tem, sim. Temos que dar nossos nomes e fazer o pagamento aqui."], ["Okay. The sign says every learner has to wear a helmet. Do you have one?", "Certo. A placa diz que todo aprendiz tem que usar capacete. Você tem um?"], ["I have mine, but your helmet is too big. Take this smaller one.", "Eu tenho o meu, mas seu capacete está grande demais. Pegue este menor."], ["Thanks! Where's the bike rack? And what's the code for my bike?", "Obrigada! Onde fica o bicicletário? E qual é o código da minha bicicleta?"], ["It's on your receipt. Be careful at the roundabout near the park.", "Está no seu recibo. Cuidado na rotatória perto do parque."], ["I will. Look, the front tire is flat! Can we get another bike?", "Vou, sim. Olha, o pneu da frente está vazio! Podemos pegar outra bicicleta?"], ["Sure. Let's ask the rental worker. I'm sure he'll help us.", "Claro. Vamos pedir ao funcionário da loja. Tenho certeza de que ele vai nos ajudar."]], ["/h/ em helmet e have", "O “h” de “helmet” e “have” é só um sopro leve de ar saindo da garganta, como quando você embaça um vidro. Em português o h é mudo, então lembre de soprar antes da vogal.", ["helmet", "have"]], ["Ana ___ sign up first.", "has to", "have to", "A Ana tem que se inscrever primeiro.", "Com Ana (she) usamos has to; have to é para I, you, we e they."], [["Everyone has to wear a helmet, and it has to fit well.", "Todo mundo tem que usar capacete, e ele tem que servir bem."], ["Yes, we do. We have to give our names and make the payment here.", "Tem, sim. Temos que dar nossos nomes e fazer o pagamento aqui."]], [{"t": "c", "q": "We ___ wear helmets at the rental shop.", "o": ["have to", "has to", "to have"], "pt": "Temos que usar capacete na loja de aluguel.", "why": "Com we usamos have to + verbo."}, {"t": "l", "say": "I have to sign up first.", "o": ["I have to sign up first.", "I had to sign up first.", "He has to sign up first."], "why": "Ouça o sujeito (I) e o tempo (have, presente)."}, {"t": "b", "pt": "Nós temos que pagar aqui.", "w": ["We", "have", "to", "pay", "here"]}, {"t": "b", "pt": "Ela tem que usar capacete.", "w": ["She", "has", "to", "wear", "a", "helmet"]}]];
englishA2PhotoThemes[116]="map";
englishA2Plans[117]={"title": "Dia livre no home office", "file": "", "grammar": "Don't have to / doesn't have to", "goal": "Diga o que não é obrigatório.", "words": [["remote", "remoto"], ["workload", "carga de trabalho"], ["podcast", "podcast"], ["work from home", "trabalhar de casa"], ["inbox", "caixa de entrada"], ["spreadsheet", "planilha"], ["commute", "trajeto ao trabalho"], ["invoice", "fatura"]]};
englishA2Content[117]=[[["Dan works remote on Fridays, so he doesn't have to take the shuttle.", "O Dan trabalha remoto às sextas, então não precisa pegar o ônibus da empresa."], ["Today he doesn't have a commute, so he stays in bed ten more minutes.", "Hoje ele não tem trajeto até o trabalho, então fica na cama mais dez minutos."], ["He makes coffee, listens to a podcast, and checks his inbox.", "Ele faz café, ouve um podcast e confere a caixa de entrada."], ["His workload is light, but the deadline is tomorrow, and his head hurts a little.", "A carga de trabalho dele é leve, mas o prazo é amanhã, e a cabeça dele dói um pouco."], ["He opens a spreadsheet and sends one invoice.", "Ele abre uma planilha e envia uma fatura."], ["He doesn't have to dress up, so he works in his pajamas.", "Ele não precisa se arrumar, então trabalha de pijama."]], [["Hi, Lia! Do you work from home today?", "Oi, Lia! Você trabalha de casa hoje?"], ["Yes, I do. I don't have to go to the office on Mondays.", "Trabalho, sim. Não preciso ir ao escritório às segundas."], ["Lucky you! I have to be there, but I don't have to wear a suit.", "Que sorte! Eu tenho que estar lá, mas não preciso usar terno."], ["That's nice. I'm on mute during calls, so I can work in my pajamas.", "Que legal. Fico no mudo durante as chamadas, então posso trabalhar de pijama."], ["Ha! Do you need help with the spreadsheet? I can send you my notes.", "Ha! Você precisa de ajuda com a planilha? Posso te mandar minhas anotações."], ["Thanks, but my boss says I don't have to finish everything today.", "Obrigada, mas meu chefe diz que não preciso terminar tudo hoje."], ["Good. There's a rumor that your deadline will probably move. Fingers crossed!", "Ótimo. Tem um boato de que seu prazo provavelmente vai mudar. Torcendo!"], ["Thanks, Dan. I'll send you the spreadsheet tonight, and we'll talk again soon.", "Obrigada, Dan. Mando a planilha hoje à noite, e a gente conversa de novo em breve."]], ["/ɛd/ em deadline e head", "Em “head” e “deadline” o “ea/e” soa como o “é” aberto de “pé”, seguido de um “d” rápido com a língua atrás dos dentes de cima. Não diga “hid” nem “hide”.", ["deadline", "head"]], ["She ___ go to the office on Fridays.", "doesn't have to", "don't have to", "Ela não precisa ir ao escritório às sextas.", "Com she usamos doesn't have to; don't have to é para I, you, we e they."], [["Yes, I do. I don't have to go to the office on Mondays.", "Trabalho, sim. Não preciso ir ao escritório às segundas."], ["Thanks, but my boss says I don't have to finish everything today.", "Obrigada, mas meu chefe diz que não preciso terminar tudo hoje."]], [{"t": "c", "q": "We ___ wear a suit at home.", "o": ["don't have to", "doesn't have to", "have not"], "pt": "Não precisamos usar terno em casa.", "why": "Com we usamos don't have to + verbo."}, {"t": "l", "say": "You don't have to work today.", "o": ["You don't have to work today.", "You don't have to walk today.", "You don't have to work tonight."], "why": "Ouça work e today."}, {"t": "b", "pt": "Eu não preciso pegar o ônibus hoje.", "w": ["I", "don't", "have", "to", "take", "the", "bus", "today"]}, {"t": "b", "pt": "Ele não precisa trabalhar no sábado.", "w": ["He", "doesn't", "have", "to", "work", "on", "Saturday"]}]];
