englishA2Plans[141]={"title": "Pet shop e acessórios", "file": "", "grammar": "Oração relativa com that", "goal": "Descreva coisas com that.", "words": [["birdseed", "ração de pássaro"], ["aquarium", "aquário"], ["ferret", "furão"], ["whiskers", "bigodes (de animal)"], ["lizard", "lagarto"], ["treat", "petisco"], ["shampoo", "xampu"], ["feed", "alimentar"], ["stroll", "passear"]]};
englishA2Content[141]=[[["Lia and her son Noah go to a pet shop near the park.", "Lia e o filho Noah vão a um pet shop perto do parque."], ["She likes to stock up on birdseed in bulk.", "Ela gosta de estocar ração de pássaro em grande quantidade."], ["The shop has an aquarium that is full of colorful fish.", "A loja tem um aquário que está cheio de peixes coloridos."], ["Noah sees a ferret that has long whiskers.", "O Noah vê um furão que tem bigodes longos."], ["A dog that can bark loudly sits by the door.", "Um cachorro que sabe latir alto fica sentado perto da porta."], ["They buy a new leash and carry the shopping bag home.", "Eles compram uma coleira de passeio nova e levam a sacola para casa."]], [["Noah, which pet do you want to see first?", "Noah, qual bicho você quer ver primeiro?"], ["I like the kitten that is sleeping in the cage.", "Eu gosto do gatinho que está dormindo na gaiola."], ["She's cute! But we need a collar for Max first.", "Ela é fofa! Mas primeiro precisamos de uma coleira para o Max."], ["Look, this collar is blue and soft. Let's get it.", "Olha, esta coleira é azul e macia. Vamos levar."], ["Good idea. Is there a bowl that's big enough for him?", "Boa ideia. Tem uma tigela que seja grande o bastante para ele?"], ["Yes, this one is. We also need shampoo and treats for Max.", "Tem, esta aqui. Também precisamos de xampu e petiscos para o Max."], ["Right. I always feed him twice a day.", "Certo. Eu sempre alimento ele duas vezes por dia."], ["Look at that lizard! Its tail is so long.", "Olha aquele lagarto! O rabo dele é tão comprido."], ["Cool! Let's pay now and stroll to the park. Max loves to bark at other dogs there.", "Legal! Vamos pagar agora e passear até o parque. O Max adora latir para os outros cachorros lá."], ["Okay. I'll carry the shopping bag.", "Certo. Eu levo a sacola."]], ["/ɑr/ em bark e park", "Para o /ɑr/ de bark e park, abra bem a boca como em 'ah' e depois puxe a língua para trás para formar o r. Não faça o 'rr' forte de 'carro'.", ["bark", "park"]], ["She has a parrot ___ talks a lot.", "that", "where", "Ela tem um papagaio que fala muito.", "That liga a coisa ou animal à descrição dele; where é só para lugares."], [["The shop has an aquarium that is full of colorful fish.", "A loja tem um aquário que está cheio de peixes coloridos."], ["I like the kitten that is sleeping in the cage.", "Eu gosto do gatinho que está dormindo na gaiola."]], [{"t": "c", "q": "I want a collar ___ is blue.", "o": ["that", "who", "where"], "pt": "Eu quero uma coleira que seja azul.", "why": "A coleira é uma coisa, então usamos that; who é para pessoas e where para lugares."}, {"t": "l", "say": "The aquarium that is near the door has big fish.", "o": ["The aquarium that is near the door has big fish.", "The aquarium that is near the door has small fish.", "The aquarium that is near the window has big fish."], "why": "O aquário está perto da porta (door) e tem peixes grandes (big)."}, {"t": "b", "pt": "Eu quero o gatinho que está dormindo.", "w": ["I", "want", "the", "kitten", "that", "is", "sleeping"]}, {"t": "b", "pt": "A gaiola que é azul é nova.", "w": ["The", "cage", "that", "is", "blue", "is", "new"]}]];
