englishA2Plans[144]={"title": "O livro que eu li", "file": "", "grammar": "Pronome relativo omitido", "goal": "Descreva algo sem usar that.", "words": [["paperback", "livro de bolso"], ["bestseller", "best-seller"], ["chapter", "capítulo"], ["page-turner", "livro envolvente"], ["mystery", "mistério"], ["writer", "escritor"], ["sequel", "continuação"], ["detective", "detetive"]]};
englishA2Content[144]=[[["Ana loves the paperback she bought at the clearance table.", "A Ana adora o livro de bolso que ela comprou na mesa de liquidação."], ["It's a bestseller everyone is talking about.", "É um best-seller de que todo mundo está falando."], ["The writer is a woman she saw on TV.", "A escritora é uma mulher que ela viu na TV."], ["The first chapter is a real page-turner.", "O primeiro capítulo é envolvente de verdade."], ["The mystery caught her attention at once.", "O mistério prendeu a atenção dela de imediato."], ["She keeps the detective novel she is reading in her shopping bag.", "Ela guarda o romance de detetive que está lendo na sacola de compras."]], [["Ana, what are you reading on the train?", "Ana, o que você está lendo no trem?"], ["A novel my sister gave me. It's a bestseller, and there's a sequel.", "Um romance que minha irmã me deu. É um best-seller, e tem uma continuação."], ["Is it good? I want a book for my trip.", "É bom? Quero um livro para a minha viagem."], ["It's a real page-turner. The first chapter caught me right away.", "É envolvente de verdade. O primeiro capítulo me prendeu logo."], ["Who's the author?", "Quem é a autora?"], ["She's a woman I saw on TV. She's from my hometown.", "É uma mulher que eu vi na TV. Ela é da minha cidade natal."], ["Cool. Does it have a happy ending?", "Legal. Tem um final feliz?"], ["I won't tell you. Borrow it, or buy it at the bookstore.", "Não vou contar. Pegue emprestado ou compre na livraria."]], ["/ɔ/ em author e caught", "O /ɔ/ de author e caught é um 'ó' aberto, com a boca bem aberta e os lábios um pouco arredondados. Em caught, o 'gh' é mudo: soa 'cót'.", ["author", "caught"]], ["The book ___ read was a bestseller.", "I", "it", "O livro que eu li era um best-seller.", "Sem that, o sujeito (I) vem direto depois do substantivo; it repetiria o objeto."], [["Ana loves the paperback she bought at the clearance table.", "A Ana adora o livro de bolso que ela comprou na mesa de liquidação."], ["She's a woman I saw on TV. She's from my hometown.", "É uma mulher que eu vi na TV. Ela é da minha cidade natal."]], [{"t": "c", "q": "The woman Ana ___ on TV is an author.", "o": ["saw", "see", "seeing"], "pt": "A mulher que a Ana viu na TV é uma autora.", "why": "Sem that, a oração continua com sujeito + verbo no passado (Ana saw)."}, {"t": "l", "say": "The book I read was a page-turner.", "o": ["The book I read was a page-turner.", "The book I read was a bestseller.", "The book I bought was a page-turner."], "why": "A frase diz que o livro que li era um page-turner."}, {"t": "b", "pt": "O livro que eu li era bom.", "w": ["The", "book", "I", "read", "was", "good"]}, {"t": "b", "pt": "A escritora que eu vi é famosa.", "w": ["The", "writer", "I", "saw", "is", "famous"]}]];
