englishA2Plans[145]={"title": "Como o pão é feito", "file": "", "grammar": "Voz passiva no presente simples", "goal": "Descreva um processo usando is made e are sold.", "words": [["yeast", "fermento"], ["flour mill", "moinho de farinha"], ["loaf", "pão de forma"], ["bake from scratch", "assar do zero"], ["knead", "sovar"], ["grain", "grão"], ["crust", "casca do pão"], ["rise", "crescer"]]};
englishA2Content[145]=[[["Bread is made from flour, water, and yeast.", "O pão é feito de farinha, água e fermento."], ["Wheat, a grain, is grown on big farms and sent to a flour mill.", "O trigo, um grão, é cultivado em fazendas grandes e enviado a um moinho de farinha."], ["At the mill, it is turned into flour and put in sacks.", "No moinho, ele é transformado em farinha e colocado em sacos."], ["In a bakery, the dough is kneaded by hand and left to rise.", "Numa padaria, a massa é sovada à mão e deixada para crescer."], ["A fresh loaf is baked in a hot oven.", "Um pão fresco é assado num forno quente."], ["Many loaves are sold before noon, and the crust is still warm.", "Muitos pães são vendidos antes do meio-dia, e a casca ainda está quente."]], [["Noah, how do they make bread?", "Noah, como se faz pão?"], ["First, wheat is taken to a flour mill. Then flour is mixed with water and yeast.", "Primeiro, o trigo é levado a um moinho. Depois a farinha é misturada com água e fermento."], ["And then the dough goes in the oven, right?", "E aí a massa vai para o forno, certo?"], ["Yes. It's baked for about forty minutes.", "Isso. Ela é assada por uns quarenta minutos."], ["I want to bake from scratch this weekend. My hometown has the best bread.", "Quero assar do zero neste fim de semana. Minha cidade natal tem o melhor pão."], ["Great! A loaf is easy to make at home. I read a chapter about it in a paperback.", "Ótimo! Um pão de forma é fácil de fazer em casa. Li um capítulo sobre isso num livro de bolso."], ["Where can I buy yeast near my house?", "Onde posso comprar fermento perto de casa?"], ["It's sold in small packages near the flour.", "Ele é vendido em pacotinhos perto da farinha."]], ["/oʊ/ em dough e loaf", "O /oʊ/ de dough e loaf começa em 'ô' e desliza para 'u', com os lábios se fechando: dough soa 'dôu' (o gh é mudo) e loaf soa 'lôuf'.", ["dough", "loaf"]], ["Many loaves ___ sold before noon.", "are", "is", "Muitos pães são vendidos antes do meio-dia.", "Loaves é plural, então a passiva usa are + particípio."], [["Bread is made from flour, water, and yeast.", "O pão é feito de farinha, água e fermento."], ["At the mill, it is turned into flour and put in sacks.", "No moinho, ele é transformado em farinha e colocado em sacos."]], [{"t": "c", "q": "Wheat ___ grown on big farms.", "o": ["is", "are", "does"], "pt": "O trigo é cultivado em fazendas grandes.", "why": "Wheat é singular; a passiva do presente usa is + particípio."}, {"t": "l", "say": "Flour is made at the mill.", "o": ["Flour is made at the mill.", "Flour is made at the farm.", "Flour is sold at the mill."], "why": "A farinha é feita (made) no moinho (mill)."}, {"t": "b", "pt": "O pão é feito com farinha.", "w": ["Bread", "is", "made", "with", "flour"]}, {"t": "b", "pt": "Os pães são vendidos na padaria.", "w": ["Loaves", "are", "sold", "at", "the", "bakery"]}]];
