englishA2Plans[146]={"title": "Chegando atrasado a uma festa de bairro", "file": "", "grammar": "Dedução com must be e can't be", "goal": "Deduza o que é verdade usando must be e can't be.", "words": [["doorbell", "campainha"], ["confetti", "confete"], ["sparkler", "vela de faíscas"], ["turn up", "aparecer"], ["lawn", "gramado"], ["streamer", "fita decorativa"], ["cupcake", "cupcake"], ["barbecue", "churrasco"]]};
englishA2Content[146]=[[["Sam is late for the neighborhood party in the suburb.", "O Sam está atrasado para a festa do bairro no subúrbio."], ["He hears loud music, and streamers and balloons hang on the porch.", "Ele ouve música alta, e fitas decorativas e balões estão pendurados na varanda."], ["Confetti is on the lawn, but nobody answers the doorbell.", "Tem confete no gramado, mas ninguém atende a campainha."], ["The house can't be empty, so everyone must be in the backyard.", "A casa não pode estar vazia, então todo mundo deve estar no quintal."], ["Through the window, he sees a sparkler and a big silver bell.", "Pela janela, ele vê uma vela de faíscas e um grande sino prateado."], ["Finally, a girl opens the door and smiles.", "Finalmente, uma menina abre a porta e sorri."]], [["Sam! You're late. We started two hours ago.", "Sam! Você está atrasado. Começamos há duas horas."], ["I know, sorry. I rang the doorbell, but nobody answered.", "Eu sei, desculpe. Toquei a campainha, mas ninguém atendeu."], ["Really? The music must be too loud.", "Sério? A música deve estar alta demais."], ["It must be! I heard it from the street.", "Deve estar mesmo! Eu ouvi da rua."], ["Why didn't you turn up earlier? Dinner is over.", "Por que você não apareceu mais cedo? O jantar acabou."], ["My bus was late. Who is the man with the sparkler near the barbecue?", "Meu ônibus atrasou. Quem é o homem com a vela de faíscas perto do churrasco?"], ["That must be Ben's uncle. He's from my hometown.", "Esse deve ser o tio do Ben. Ele é da minha cidade natal."], ["Ha! Are there any cupcakes left? I'm hungry.", "Ha! Sobrou algum cupcake? Estou com fome."], ["Yes, there are two. I like to bake from scratch.", "Sim, tem dois. Eu gosto de assar do zero."], ["Great! I'll get a plate and some punch.", "Ótimo! Vou pegar um prato e um pouco de ponche."]], ["/b/ em balloon e bell", "O /b/ é igual ao b do português: feche os lábios, solte o ar e faça a voz vibrar. Não acrescente um 'i' depois: é balloon, não 'bi-lun', e bell, não 'béu-i'.", ["balloon", "bell"]], ["The lights are on, so someone ___ be home.", "must", "can't", "As luzes estão acesas, então alguém deve estar em casa.", "Com luzes acesas, a dedução é positiva: must be; can't be seria o contrário."], [["The house can't be empty, so everyone must be in the backyard.", "A casa não pode estar vazia, então todo mundo deve estar no quintal."], ["Really? The music must be too loud.", "Sério? A música deve estar alta demais."]], [{"t": "c", "q": "The house is dark and quiet. Nobody ___ be home.", "o": ["can't", "must", "does"], "pt": "A casa está escura e quieta. Ninguém deve estar em casa.", "why": "Com a casa escura e quieta, a dedução é negativa: can't be."}, {"t": "l", "say": "That must be Ben's uncle.", "o": ["That must be Ben's uncle.", "That can't be Ben's uncle.", "That must be Ben's aunt."], "why": "A dedução é positiva (must) e fala do tio (uncle)."}, {"t": "b", "pt": "Ele deve estar no quintal.", "w": ["He", "must", "be", "in", "the", "backyard"]}, {"t": "b", "pt": "Isso não pode ser verdade.", "w": ["That", "can't", "be", "true"]}]];
