englishA2Plans[147]={"title": "Placas da fábrica de móveis", "file": "", "grammar": "Passiva no presente: negativas e perguntas", "goal": "Faça perguntas e negações na passiva.", "words": [["sawdust", "serragem"], ["assembly line", "linha de montagem"], ["lumber", "madeira serrada"], ["safety vest", "colete refletivo"], ["forklift", "empilhadeira"], ["pallet", "palete"], ["earplugs", "protetores de ouvido"], ["cabinet", "armário"]]};
englishA2Content[147]=[[["Rosa visits a furniture factory with her class.", "A Rosa visita uma fábrica de móveis com a turma."], ["Workers turn up at six, and the first shift starts at seven.", "Os operários aparecem às seis, e o primeiro turno começa às sete."], ["The lumber isn't cut by hand; it is cut by a big machine.", "A madeira não é cortada à mão; ela é cortada por uma máquina grande."], ["Sawdust is cleaned from the floor, and boards are moved on pallets by a forklift.", "A serragem é limpa do chão, e as tábuas são movidas em paletes por uma empilhadeira."], ["On the assembly line, drawers are made and cabinets are painted.", "Na linha de montagem, gavetas são feitas e armários são pintados."], ["Phones aren't allowed here, so visitors hand in their phones at the door.", "Celulares não são permitidos aqui, então os visitantes entregam o celular na porta."]], [["Excuse me, do I need goggles in this room?", "Com licença, preciso de óculos de proteção nesta sala?"], ["Yes, you do. And please wear your safety vest and earplugs.", "Sim, precisa. E use o colete refletivo e os protetores de ouvido, por favor."], ["Of course. Is the lumber cut here?", "Claro. A madeira é cortada aqui?"], ["No, it isn't. It arrives already cut.", "Não, não é. Ela chega já cortada."], ["I see. What happens on the assembly line?", "Entendi. O que acontece na linha de montagem?"], ["Workers build the drawers and add the glue.", "Os operários montam as gavetas e passam a cola."], ["And all this sawdust? It's like snow in my hometown!", "E toda essa serragem? Parece neve na minha cidade natal!"], ["Don't worry, it isn't thrown away. A farm buys it every week.", "Não se preocupe, ela não é jogada fora. Uma fazenda compra toda semana."]], ["/ɔ/ em sawdust e lumber", "Em sawdust, 'saw' tem um 'ó' aberto, com a boca bem aberta e os lábios um pouco arredondados. Já a primeira vogal de lumber é curta e relaxada, parecida com 'lãm'.", ["sawdust", "lumber"]], ["Phones ___ allowed near the machines.", "aren't", "don't", "Celulares não são permitidos perto das máquinas.", "Na passiva negativa usamos are not (aren't) + particípio; don't não combina com allowed."], [["The lumber isn't cut by hand; it is cut by a big machine.", "A madeira não é cortada à mão; ela é cortada por uma máquina grande."], ["Of course. Is the lumber cut here?", "Claro. A madeira é cortada aqui?"]], [{"t": "c", "q": "___ the drawers made by hand?", "o": ["Are", "Do", "Is"], "pt": "As gavetas são feitas à mão?", "why": "Drawers é plural; a pergunta na passiva começa com Are + sujeito + particípio."}, {"t": "l", "say": "Is sawdust cleaned every hour?", "o": ["Is sawdust cleaned every hour?", "Is sawdust cleaned every day?", "Does sawdust clean every hour?"], "why": "A pergunta é se a serragem é limpa a cada hora (every hour)."}, {"t": "b", "pt": "A madeira não é cortada à mão.", "w": ["The", "lumber", "isn't", "cut", "by", "hand"]}, {"t": "b", "pt": "As gavetas são feitas aqui?", "w": ["Are", "the", "drawers", "made", "here"]}]];
