englishA2Plans[149]={"title": "Revisão: Jantar de domingo na casa dos pais", "file": "", "grammar": "Revisão: quantificadores, comparativos e would", "goal": "Peça e ofereça comida em um jantar de família.", "words": [["roast", "assado"], ["gravy", "molho de carne"], ["leftovers", "sobras"], ["serving dish", "travessa"], ["stuffing", "recheio"], ["pudding", "pudim"], ["jug", "jarra"], ["side dish", "acompanhamento"]]};
englishA2Content[149]=[[["Every Sunday, Tom eats dinner at his parents' house.", "Todo domingo, o Tom janta na casa dos pais."], ["When the doorbell rings, the smell of roast is already in the hall.", "Quando a campainha toca, o cheiro de assado já está no corredor."], ["His mother makes plenty of gravy, and she puts a warm loaf on the table.", "A mãe dele faz bastante molho e coloca um pão quente na mesa."], ["The serving dish has a few potatoes and lots of beans.", "A travessa tem algumas batatas e muito feijão."], ["Tom thinks this roast is better than last week's.", "O Tom acha este assado melhor que o da semana passada."], ["After dinner, there are lots of leftovers, and everybody takes some home.", "Depois do jantar, sobram muitas coisas, e todo mundo leva um pouco para casa."]], [["Tom, would you like some more roast and stuffing?", "Tom, você quer mais um pouco de assado e recheio?"], ["Yes, please. It's better than last week's.", "Quero, por favor. Está melhor que o da semana passada."], ["Thanks. Did you take enough gravy?", "Obrigada. Você pegou molho suficiente?"], ["Not really. Could I have a little more?", "Na verdade, não. Posso pegar mais um pouco?"], ["Of course. There's plenty in the pot.", "Claro. Tem bastante na panela."], ["Mom, did you bake from scratch again? This loaf is amazing.", "Mãe, você assou do zero de novo? Este pão está incrível."], ["I did. It's easier than you think.", "Assei. É mais fácil do que você pensa."], ["Maybe I'll try it. Is there any pudding?", "Talvez eu tente. Tem pudim?"], ["There's a little pudding, but we don't have enough napkins.", "Tem um pouco de pudim, mas não temos guardanapos suficientes."], ["No problem. I'll get the jug and some napkins.", "Sem problema. Vou pegar a jarra e uns guardanapos."]], ["/eɪ/ em gravy e table", "O /eɪ/ começa em 'ê' e desliza para 'i', como o 'êi' de 'lei': gravy soa como 'grêivi' e table como 'têibol'. Não corte o som no meio.", ["gravy", "table"]], ["Could I have ___ more gravy, please?", "a little", "a few", "Posso pegar mais um pouco de molho, por favor?", "Gravy não se conta, então usamos a little; a few é para coisas contáveis."], [["Of course. There's plenty in the pot.", "Claro. Tem bastante na panela."], ["Not really. Could I have a little more?", "Na verdade, não. Posso pegar mais um pouco?"]], [{"t": "c", "q": "There are ___ potatoes in the dish.", "o": ["a few", "a little", "much"], "pt": "Tem algumas batatas na travessa.", "why": "Potatoes é contável no plural, então usamos a few."}, {"t": "l", "say": "Would you like some more roast?", "o": ["Would you like some more roast?", "Would you like some more toast?", "Would you like some more rice?"], "why": "A pergunta oferece mais assado (roast)."}, {"t": "b", "pt": "Você quer um pouco mais de molho?", "w": ["Would", "you", "like", "a", "little", "more", "gravy"]}, {"t": "b", "pt": "Este assado é melhor que aquele.", "w": ["This", "roast", "is", "better", "than", "that", "one"]}]];
