englishA2MiniStories[149]=["O molho que sumiu", "Last Sunday, Mom cooked a big roast for the family.~No domingo passado, a mamãe fez um assado grande para a família.|She made plenty of gravy and put it on the table.~Ela fez bastante molho e colocou na mesa.|But when Dad sat down, the serving dish was empty.~Mas quando o papai sentou, a travessa estava vazia.|\"Where did the gravy go?\" he asked.~\"Para onde foi o molho?\", ele perguntou.|Everybody looked at the table and shook their heads.~Todo mundo olhou para a mesa e balançou a cabeça.|Then they heard a noise under the table.~Então ouviram um barulho debaixo da mesa.|Max, the small dog, was there with gravy on his nose.~Max, o cachorrinho, estava lá com molho no focinho.|Everyone laughed, even Dad.~Todo mundo riu, até o papai.|Mom made more gravy, and it was better than before.~A mamãe fez mais molho, e ficou melhor que antes.|After dinner, Max got the leftovers and he was very happy.~Depois do jantar, o Max ganhou as sobras e ficou muito feliz."];
englishA2ExtraWordExamples[149]={"side dish": ["Mom said she would make a side dish.", "A mamãe disse que faria um acompanhamento."]};
englishA2Plans[150]={"title": "Contando a quem se deve o crédito", "file": "", "grammar": "Passiva com by (agente)", "goal": "Diga quem fez algo usando by.", "words": [["painter", "pintor"], ["sculpture", "escultura"], ["masterpiece", "obra-prima"], ["on display", "em exibição"], ["sculptor", "escultor"], ["portrait", "retrato"], ["landscape", "paisagem"], ["watercolor", "aquarela"]]};
englishA2Content[150]=[[["Mia and her dad visit the city museum on Sunday.", "Mia e o pai dela visitam o museu da cidade no domingo."], ["The big sculpture in the hall was made by a famous sculptor.", "A grande escultura no salão foi feita por um escultor famoso."], ["Next to it, a landscape in watercolor is on display.", "Ao lado dela, uma paisagem em aquarela está em exibição."], ["It was painted by a painter from Texas named Ana Ruiz.", "Ela foi pintada por uma pintora do Texas chamada Ana Ruiz."], ["Mia likes the old portrait, but her dad likes the dinosaur skeleton more.", "Mia gosta do retrato antigo, mas o pai dela gosta mais do esqueleto de dinossauro."], ["\"This is a real masterpiece,\" Mia says, and she takes a photo.", "\"Isso é uma verdadeira obra-prima\", diz Mia, e ela tira uma foto."]], [["Dad, who made this sculpture? It looks so strong.", "Pai, quem fez esta escultura? Ela parece tão forte."], ["The sign says it was made by Leo Park. He's a sculptor from Ohio.", "A placa diz que ela foi feita por Leo Park. Ele é um escultor de Ohio."], ["Wow. And who painted the portrait of the woman over there?", "Nossa. E quem pintou o retrato daquela mulher ali?"], ["It was painted by Ana Ruiz. She used a very small paintbrush.", "Foi pintado por Ana Ruiz. Ela usou um pincel bem pequeno."], ["Is her work always on display here?", "O trabalho dela fica sempre em exibição aqui?"], ["No, only until June. The fossil room stays open all year.", "Não, só até junho. A sala de fósseis fica aberta o ano todo."], ["Good, because I want to see the fossils again. Can we go after lunch?", "Que bom, porque quero ver os fósseis de novo. Podemos ir depois do almoço?"], ["Sure, we can go right after lunch.", "Claro, podemos ir logo depois do almoço."]], ["/p/ em painter e sculpture", "O /p/ é feito com os lábios fechados e um sopro de ar forte, como o p do português, mas em inglês o sopro é mais forte no começo de painter e sculpture. Coloque a mão na frente da boca e sinta o ar.", ["painter", "sculpture"]], ["The portrait was painted ___ Ana Ruiz.", "by", "from", "O retrato foi pintado por Ana Ruiz.", "Na voz passiva, by apresenta quem fez a ação."], [["The big sculpture in the hall was made by a famous sculptor.", "A grande escultura no salão foi feita por um escultor famoso."], ["It was painted by a painter from Texas named Ana Ruiz.", "Ela foi pintada por uma pintora do Texas chamada Ana Ruiz."]], [{"t": "c", "q": "The sculpture was made ___ a young sculptor.", "o": ["by", "with", "at"], "pt": "A escultura foi feita por um jovem escultor.", "why": "Para dizer quem fez algo na passiva, usamos by."}, {"t": "l", "say": "It was painted by a painter from Texas.", "o": ["It was painted by a painter from Texas.", "It was paid by a painter from Texas.", "It was painting by a painter from Texas."], "why": "A passiva usa was + particípio (painted), seguido de by."}, {"t": "b", "pt": "O quadro foi pintado por Ana.", "w": ["The", "painting", "was", "painted", "by", "Ana"]}, {"t": "b", "pt": "A escultura está em exibição.", "w": ["The", "sculpture", "is", "on", "display"]}]];
