englishA2Plans[163]={"title": "Preparando a viagem de avião", "file": "", "grammar": "Take off, put on, try on", "goal": "Use take off, put on e try on.", "words": [["customs", "alfândega"], ["luggage tag", "etiqueta de bagagem"], ["security check", "controle de segurança"], ["take off", "tirar / decolar"], ["metal detector", "detector de metais"], ["luggage cart", "carrinho de bagagem"], ["seat belt", "cinto de segurança"], ["duty-free", "loja de isentos"]]};
englishA2Content[163]=[[["Mia is at the airport with her big suitcase on a luggage cart.", "A Mia está no aeroporto com a mala grande num carrinho de bagagem."], ["First she puts a luggage tag on the suitcase.", "Primeiro ela coloca uma etiqueta de bagagem na mala."], ["At the security check, she takes her jacket off before the metal detector.", "No controle de segurança, ela tira a jaqueta antes do detector de metais."], ["The officer looks at her passport and her boarding pass.", "O oficial olha o passaporte e o cartão de embarque dela."], ["Her plane takes off at ten, so she puts her seat belt on.", "O avião dela decola às dez, então ela põe o cinto de segurança."], ["She is going to hit the slopes in Canada!", "Ela vai esquiar no Canadá!"]], [["Do you have your passport and boarding pass, Mia?", "Você está com o passaporte e o cartão de embarque, Mia?"], ["Yes, they're in my bag. I also put a luggage tag on the suitcase.", "Sim, estão na minha bolsa. Também coloquei uma etiqueta na mala."], ["Good. At the security check, you have to take off your shoes and your belt.", "Bom. No controle de segurança, você tem que tirar os sapatos e o cinto."], ["I know. Last time I forgot, and I waited at customs for an hour.", "Eu sei. Da última vez esqueci e esperei uma hora na alfândega."], ["Wait, let's go to the duty-free shop first. Try this warm hat on.", "Espere, vamos primeiro à loja duty-free. Experimente este chapéu quente."], ["It looks great! I'll put it on for the trip. Do you have your lift ticket and ski poles?", "Ficou ótimo! Vou usá-lo na viagem. Você tem o ingresso do teleférico e os bastões de esqui?"], ["Yes, everything is in my backpack. Our plane leaves at ten, so let's hurry.", "Sim, está tudo na minha mochila. Nosso avião sai às dez, então vamos depressa."], ["Okay, let's go! I can't wait to hit the slopes.", "Certo, vamos! Mal posso esperar para esquiar."]], ["/ɛ/ em security e check", "Em security e check, o \"e\" é aberto, como o \"é\" de \"pé\". Abra bem a boca e não termine com \"i\". Em check, o \"ch\" soa como o \"tch\" de \"tchau\".", ["security", "check"]], ["At the airport, Mia takes ___ her jacket.", "off", "up", "No aeroporto, a Mia tira a jaqueta.", "Take off significa tirar uma roupa do corpo."], [["At the security check, she takes her jacket off before the metal detector.", "No controle de segurança, ela tira a jaqueta antes do detector de metais."], ["Her plane takes off at ten, so she puts her seat belt on.", "O avião dela decola às dez, então ela põe o cinto de segurança."]], [{"t": "c", "q": "This hat is nice. Try it ___, please.", "o": ["on", "off", "up"], "pt": "Este chapéu é bonito. Experimente-o, por favor.", "why": "Try on significa experimentar uma roupa para ver se serve."}, {"t": "l", "say": "Take off your shoes.", "o": ["Take off your shoes.", "Take off your shows.", "Put on your shoes."], "why": "Ouça shoes (sapatos) e take off (tire)."}, {"t": "b", "pt": "Tire a jaqueta.", "w": ["Take", "off", "your", "jacket"]}, {"t": "b", "pt": "A Mia o experimentou na loja.", "w": ["Mia", "tried", "it", "on", "in", "the", "shop"]}]];
