englishA2Plans[165]={"title": "Organizando uma reunião de equipe", "file": "", "grammar": "Set up, find out, sort out", "goal": "Use set up, find out e sort out.", "words": [["agenda", "pauta"], ["flip chart", "flip chart"], ["projector screen", "tela de projeção"], ["wrap up", "encerrar"], ["presentation", "apresentação"], ["handout", "material impresso"], ["extension cord", "extensão elétrica"], ["coffee break", "pausa para o café"]]};
englishA2Content[165]=[[["Eva has a team meeting and a presentation at nine.", "A Eva tem uma reunião de equipe e uma apresentação às nove."], ["She sets up the projector screen and the flip chart.", "Ela monta a tela de projeção e o flip chart."], ["She puts a printed agenda and a handout on every chair.", "Ela coloca uma pauta impressa e um material impresso em cada cadeira."], ["Dan wants to find out the budget, so he looks it up in his binder.", "O Dan quer descobrir o orçamento, então procura no fichário dele."], ["There is a problem with the extension cord, but they sort it out quickly.", "Há um problema com a extensão elétrica, mas eles resolvem rápido."], ["At ten they wrap the meeting up, and everybody smiles.", "Às dez eles encerram a reunião, e todo mundo sorri."]], [["Dan, can you help me set up the room? The meeting is at nine.", "Dan, você pode me ajudar a montar a sala? A reunião é às nove."], ["Sure. Should I put the projector screen near the window?", "Claro. Devo colocar a tela de projeção perto da janela?"], ["No, put it by the door. I'll show an image of the budget in my presentation.", "Não, ponha perto da porta. Vou mostrar uma imagem do orçamento na minha apresentação."], ["I can't find the marker. Did you throw away the old one?", "Não acho a caneta de quadro. Você jogou fora a velha?"], ["No, it's in my binder. We need to find out who is coming.", "Não, está no meu fichário. Precisamos descobrir quem vem."], ["Mia always oversleeps, so she isn't coming, but I think Ana is going to join us.", "A Mia sempre dorme demais, então não vem, mas acho que a Ana vai se juntar a nós."], ["Okay. If there's a problem with the laptop, we'll sort it out together.", "Certo. Se houver problema com o notebook, vamos resolver juntos."], ["Deal. We'll have a coffee break first, and then we'll wrap up at ten.", "Combinado. Vamos fazer uma pausa para o café primeiro e depois encerrar às dez."]], ["/tʃ/ em agenda e image", "Em agenda e image, o \"g\" soa como \"dj\" (como em \"adjetivo\" dito rápido), com a língua no céu da boca e a voz ligada. No fim de image, não acrescente \"i\".", ["agenda", "image"]], ["We need to find ___ who is coming.", "out", "up", "Precisamos descobrir quem vem.", "Find out significa descobrir uma informação."], [["She sets up the projector screen and the flip chart.", "Ela monta a tela de projeção e o flip chart."], ["There is a problem with the extension cord, but they sort it out quickly.", "Há um problema com a extensão elétrica, mas eles resolvem rápido."]], [{"t": "c", "q": "Please ___ the room up before nine.", "o": ["set", "sort", "find"], "pt": "Por favor, monte a sala antes das nove.", "why": "Set up significa montar ou preparar."}, {"t": "l", "say": "Let's wrap up at ten.", "o": ["Let's wrap up at ten.", "Let's warm up at ten.", "Let's wrap up at two."], "why": "Wrap up é encerrar; warm up seria aquecer."}, {"t": "b", "pt": "Podemos resolver isso juntos.", "w": ["We", "can", "sort", "it", "out", "together"]}, {"t": "b", "pt": "Eu vou descobrir quem vem.", "w": ["I", "will", "find", "out", "who", "is", "coming"]}]];
