englishA2Plans[166]={"title": "Horários e prazos na universidade", "file": "", "grammar": "Preposições de tempo: in, on, at, during, until, by", "goal": "Escolha a preposição de tempo correta.", "words": [["semester", "semestre"], ["lecture", "palestra / aula"], ["syllabus", "ementa"], ["enroll", "matricular-se"], ["assignment", "trabalho"], ["course", "curso"], ["exam", "prova"], ["textbook", "livro didático"]]};
englishA2Content[166]=[[["The new semester starts in September.", "O novo semestre começa em setembro."], ["Leo enrolls in a history course on Monday.", "O Leo se matricula num curso de história na segunda."], ["The lecture is at nine, and it lasts until ten thirty.", "A aula é às nove e dura até as dez e meia."], ["During the lecture, he reads the syllabus and takes notes.", "Durante a aula, ele lê a ementa e faz anotações."], ["The first assignment is due by Friday.", "O primeiro trabalho deve ser entregue até sexta."], ["He sets his alarm clock for eight, so he doesn't oversleep.", "Ele programa o despertador para as oito, para não dormir demais."]], [["Leo, how do I enroll for the new semester?", "Leo, como eu me matriculo no novo semestre?"], ["Go to the school website. You can enroll until Friday.", "Vá ao site da escola. Você pode se matricular até sexta."], ["Okay, I'll do it tonight. Which history lecture is better? I also need the textbook.", "Certo, faço isso hoje à noite. Qual aula de história é melhor? Também preciso do livro didático."], ["Take Professor Reed's. It's on Mondays at nine, and she's really funny.", "Escolha a da professora Reed. É às segundas, às nove, e ela é muito engraçada."], ["Nice! Is the syllabus online? I'd like to look it up before choosing.", "Legal! A ementa está online? Quero consultar antes de escolher."], ["Yes, it is. And the first exam is on October third.", "Está, sim. E a primeira prova é no dia três de outubro."], ["That's soon! I always oversleep, so I'll set my alarm clock early.", "Já é logo! Eu sempre durmo demais, então vou programar o despertador cedo."], ["Good plan. Then I'll see you at the lecture, Bia.", "Bom plano. Então vejo você na aula, Bia."]], ["/s/ em semester e syllabus", "Em semester e syllabus, o \"s\" é um sibilo suave, como o \"ss\" de \"passo\", sem vibrar a garganta (senão vira \"z\"). Não coloque um \"i\" ou \"e\" antes do s inicial.", ["semester", "syllabus"]], ["The lecture is ___ nine o'clock.", "at", "in", "A aula é às nove horas.", "Usamos at com horas exatas."], [["The lecture is at nine, and it lasts until ten thirty.", "A aula é às nove e dura até as dez e meia."], ["The first assignment is due by Friday.", "O primeiro trabalho deve ser entregue até sexta."]], [{"t": "c", "q": "The semester starts ___ September.", "o": ["in", "on", "at"], "pt": "O semestre começa em setembro.", "why": "Usamos in com meses: in September."}, {"t": "l", "say": "It finishes at ten thirty.", "o": ["It finishes at ten thirty.", "It finishes at ten thirteen.", "It finishes at ten forty."], "why": "Ouça thirty (30), não thirteen (13)."}, {"t": "b", "pt": "A aula começa às nove.", "w": ["The", "lecture", "starts", "at", "nine"]}, {"t": "b", "pt": "Preciso terminar até sexta-feira.", "w": ["I", "must", "finish", "it", "by", "Friday"]}]];
