englishA2Plans[172]={"title": "Obras que ainda não acabaram", "file": "", "grammar": "Still, anymore e no longer", "goal": "Fale de algo que continua ou deixou de ser usando still e anymore.", "words": [["scaffold", "andaime"], ["cement", "cimento"], ["bulldozer", "escavadeira"], ["under construction", "em construção"], ["wheelbarrow", "carrinho de mão"], ["gravel", "cascalho"], ["trench", "vala"], ["dump truck", "caminhão basculante"]]};
englishA2Content[172]=[[["The new plaza is still under construction.", "A praça nova ainda está em construção."], ["Workers mix cement and push gravel in a wheelbarrow.", "Os operários misturam cimento e empurram cascalho num carrinho de mão."], ["A big crane lifts bricks over a deep trench.", "Um guindaste grande levanta tijolos sobre uma vala funda."], ["A bulldozer moves dirt near a tall scaffold.", "Uma escavadeira move terra perto de um andaime alto."], ["The old gazebo no longer stands there, and a crack runs through the wall.", "O coreto velho não está mais lá, e uma rachadura atravessa o muro."], ["Noah still waits for the park to open.", "Noah ainda espera o parque abrir."]], [["Mia, is the plaza still under construction?", "Mia, a praça ainda está em construção?"], ["Yes, it is. They need to build the new gazebo.", "Está, sim. Eles precisam construir o coreto novo."], ["Really? I thought it was ready last month. I walk by every day.", "Sério? Achei que estava pronta no mês passado. Passo por lá todo dia."], ["I know. Now there's a bulldozer across from the bakery, and I can't cross there anymore.", "Eu sei. Agora tem uma escavadeira em frente à padaria, e não consigo mais atravessar ali."], ["That's annoying. Do you go to the cafe on that corner?", "Que chato. Você vai ao café daquela esquina?"], ["No, I don't go there anymore. The dust gets into my coffee.", "Não, não vou mais lá. A poeira cai no meu café."], ["Ha! At least you don't need a helmet.", "Ha! Pelo menos você não precisa de capacete."], ["True. But the scaffold is up until June, so be careful.", "Verdade. Mas o andaime fica até junho, então tome cuidado."]], ["/k/ em crane e brick", "O som /k/ de crane e brick: é o 'c' de 'casa', mas em inglês sai com um sopro de ar logo depois, em crane e brick no começo e no fim da palavra.", ["crane", "brick"]], ["I don't live there ___.", "anymore", "still", "Eu não moro mais lá.", "Anymore vem no fim da frase negativa e quer dizer 'não mais'."], [["Mia, is the plaza still under construction?", "Mia, a praça ainda está em construção?"], ["No, I don't go there anymore. The dust gets into my coffee.", "Não, não vou mais lá. A poeira cai no meu café."]], [{"t": "c", "q": "The building is ___ under construction.", "o": ["still", "anymore", "ever"], "pt": "O prédio ainda está em construção.", "why": "Still significa 'ainda' numa frase afirmativa."}, {"t": "l", "say": "She no longer works here.", "o": ["She no longer works here.", "She still works here.", "She now longer works here."], "why": "No longer quer dizer 'não mais'."}, {"t": "b", "pt": "A ponte ainda está em construção.", "w": ["The", "bridge", "is", "still", "under", "construction"]}, {"t": "b", "pt": "Eu não uso mais capacete.", "w": ["I", "don't", "wear", "a", "helmet", "anymore"]}]];
