englishA2Plans[179]={"title": "Revisão: Dia de esportes na escola", "file": "", "grammar": "Revisão: -ing e to, passiva e comparativos", "goal": "Fale de gostos e planos no dia de esportes.", "words": [["relay race", "corrida de revezamento"], ["referee", "árbitro"], ["sprint", "corrida de velocidade"], ["sports day", "dia de esportes"], ["baton", "bastão de revezamento"], ["hurdle", "barreira"], ["scoreboard", "placar"], ["starting line", "linha de largada"]]};
englishA2Content[179]=[[["Today is sports day at Lia's school.", "Hoje é o dia de esportes na escola da Lia."], ["Students sign in at the meeting point near the track.", "Os alunos registram presença no ponto de encontro perto da pista."], ["The teacher does a head count before the first race.", "A professora conta os alunos antes da primeira prova."], ["Lia loves running, but she isn't as fast as Tom.", "Lia adora correr, mas não é tão rápida quanto o Tom."], ["In the relay race, the runners pass a baton to each other.", "Na corrida de revezamento, os corredores passam um bastão uns aos outros."], ["The referee blows his whistle, and the sprint begins.", "O árbitro apita, e a corrida de velocidade começa."]], [["Tom, where is our group? I can't find the meeting point.", "Tom, onde está nosso grupo? Não acho o ponto de encontro."], ["It's behind the gym, next to the big tree. Everyone has to sign in there.", "Fica atrás da quadra, ao lado da árvore grande. Todo mundo precisa se registrar lá."], ["Okay. Do you know what time the relay race starts?", "Certo. Você sabe a que horas começa a corrida de revezamento?"], ["At two o'clock. I'm going to run the last part, so I'm nervous.", "Às duas. Vou correr a última parte, então estou nervoso."], ["Don't worry. You're faster than me, and you love running, don't you?", "Calma. Você é mais rápido que eu, e adora correr, não adora?"], ["I do, but the referee is strict about the jerseys, and the scoreboard shows everything.", "Adoro, mas o árbitro é rígido com as camisas, e o placar mostra tudo."], ["Our team is going to win a medal, I'm sure.", "Nosso time vai ganhar uma medalha, tenho certeza."], ["Yes! Let's find the others and do a head count.", "Sim! Vamos achar os outros e fazer a contagem."]], ["/w/ em whistle e where", "O som /w/ de whistle e where: arredonde os lábios como para dizer 'u' e solte rápido para a vogal seguinte. Em where o 'wh' soa igual a 'w'.", ["whistle", "where"]], ["Lia loves ___ in the relay race.", "running", "to running", "Lia adora correr na corrida de revezamento.", "Depois de loves usa-se -ing ou to + verbo; 'to running' está errado."], [["Tom, where is our group? I can't find the meeting point.", "Tom, onde está nosso grupo? Não acho o ponto de encontro."], ["Okay. Do you know what time the relay race starts?", "Certo. Você sabe a que horas começa a corrida de revezamento?"]], [{"t": "c", "q": "Tom is ___ than Lia.", "o": ["faster", "more fast", "fastest"], "pt": "Tom é mais rápido que Lia.", "why": "Adjetivo curto forma o comparativo com -er: faster."}, {"t": "l", "say": "The race was held on the field.", "o": ["The race was held on the field.", "The race was help on the field.", "The race was hold on the field."], "why": "A passiva usa was + held (particípio de hold)."}, {"t": "b", "pt": "Eu vou correr a última parte.", "w": ["I'm", "going", "to", "run", "the", "last", "part"]}, {"t": "b", "pt": "Ela adora correr, não adora?", "w": ["She", "loves", "running,", "doesn't", "she"]}]];
englishA2PhotoThemes[179]="notebook";
englishA2MiniStories[179]=["O dia de esportes da Lia", "On sports day, Lia and Tom wake up early.~No dia de esportes, Lia e Tom acordam cedo.|They put on their team shirts and go to school.~Eles vestem as camisas do time e vão para a escola.|The teacher checks the group and gives each student a number.~A professora confere o grupo e dá um número a cada aluno.|In the relay race, Tom runs the last part for the blue team.~Na corrida de revezamento, Tom corre a última parte pelo time azul.|Lia waits at the finish line with a bottle of water.~Lia espera na linha de chegada com uma garrafa de água.|Suddenly, Tom's shoe is loose, and he falls on the track.~De repente, o tênis do Tom está frouxo, e ele cai na pista.|Everyone gets quiet, but Tom stands up quickly.~Todos ficam em silêncio, mas Tom se levanta rápido.|He keeps running with one shoe and crosses the line first.~Ele continua correndo com um pé de tênis só e cruza a linha primeiro.|The referee blows the whistle, and the blue team wins the medal.~O árbitro apita, e o time azul ganha a medalha.|Tom laughs and says, \"I'm never going to wear old shoes again!\"~Tom ri e diz: \"Nunca mais vou usar tênis velhos!\""];
englishA2ExtraWordExamples[179]={"hurdle": ["He jumps over the first hurdle.", "Ele pula a primeira barreira."], "starting line": ["The runners stood at the starting line.", "Os corredores ficaram na linha de largada."]};
englishA2Plans[180]={"title": "Se arrumando antes da festa", "file": "", "grammar": "Pronomes reflexivos (myself, yourself)", "goal": "Fale de ações sobre si mesmo usando reflexivos.", "words": [["razor", "lâmina de barbear"], ["lotion", "hidratante"], ["hairbrush", "escova de cabelo"], ["put on makeup", "maquiar-se"], ["perfume", "perfume"], ["lipstick", "batom"], ["hairdryer", "secador de cabelo"], ["deodorant", "desodorante"]]};
englishA2Content[180]=[[["Ana is getting ready for a party at a nice venue.", "Ana está se arrumando para uma festa em um lugar bonito."], ["She looks at herself in the mirror.", "Ela se olha no espelho."], ["She combs her hair, dries it with a hairdryer, and puts on lipstick.", "Ela penteia o cabelo, seca com o secador e passa batom."], ["Her brother Ben takes a shower with her shampoo.", "O irmão dela, Ben, toma banho com o xampu dela."], ["Ouch! He cuts himself, but he's okay.", "Ai! Ele se corta, mas está bem."], ["Then he puts on deodorant and gets dressed.", "Depois ele passa desodorante e se veste."]], [["Are you ready for the party yet, Ana?", "Você já está pronta para a festa, Ana?"], ["Not yet. I need to put on makeup first.", "Ainda não. Preciso me maquiar primeiro."], ["Okay. Did you find your hairbrush and your perfume?", "Certo. Você achou sua escova de cabelo e seu perfume?"], ["Yes, I did. I can do everything myself, thanks.", "Achei. Eu consigo fazer tudo sozinha, obrigada."], ["Then I'll shave now. Where's my razor?", "Então vou me barbear agora. Cadê minha lâmina?"], ["It's next to the towel, and the lotion is there too.", "Está ao lado da toalha, e o hidratante também está ali."], ["Found it. Is the dress code formal tonight?", "Achei. O traje de hoje à noite é formal?"], ["Yes, so please don't hurt yourself with that razor!", "É, então por favor não se machuque com essa lâmina!"], ["Don't worry. I always shave myself very carefully.", "Relaxa. Eu sempre me barbeio com muito cuidado."], ["Perfect. Then I'll take the guest list, and we'll leave at eight.", "Ótimo. Então eu pego a lista de convidados e saímos às oito."]], ["/oʊ/ em comb e lotion", "O som /oʊ/ começa em 'ô' e fecha num 'u' leve, como 'ôu'. Em comb, o b final é mudo: diga 'kôum'.", ["comb", "lotion"]], ["Ana looks at ___ in the mirror.", "herself", "her", "Ana se olha no espelho.", "O sujeito e o objeto são a mesma pessoa, então usamos o reflexivo herself."], [["She looks at herself in the mirror.", "Ela se olha no espelho."], ["Ouch! He cuts himself, but he's okay.", "Ai! Ele se corta, mas está bem."]], [{"t": "c", "q": "Be careful! You can hurt ___ with that razor.", "o": ["yourself", "you", "yours"], "pt": "Cuidado! Você pode se machucar com essa lâmina.", "why": "O sujeito (you) faz a ação nele mesmo, então usamos yourself."}, {"t": "l", "say": "I can do it myself.", "o": ["I can do it myself.", "I can do it me.", "I can do it mine."], "why": "Depois de do it, o reflexivo myself significa 'eu mesmo, sozinho'."}, {"t": "b", "pt": "Ela se olha no espelho.", "w": ["She", "looks", "at", "herself", "in", "the", "mirror"]}, {"t": "b", "pt": "Eu me barbeio todo dia.", "w": ["I", "shave", "myself", "every", "day"]}]];
englishA2PhotoThemes[180]="chat";
englishA2Plans[181]={"title": "Amigos se ajudando", "file": "", "grammar": "Each other e one another", "goal": "Fale de ações recíprocas usando each other.", "words": [["argue", "discutir"], ["forgive", "perdoar"], ["apologize", "pedir desculpas"], ["make up", "fazer as pazes"], ["blame", "culpar"], ["trust", "confiar"], ["truth", "verdade"], ["hold hands", "dar as mãos"]]};
englishA2Content[181]=[[["Mia and Tom are best friends, but today they argue.", "Mia e Tom são melhores amigos, mas hoje eles discutem."], ["Tom forgot Mia's birthday, and she doesn't speak to him.", "Tom esqueceu o aniversário da Mia, e ela não fala com ele."], ["Tom knows it was his mistake, so he calls her.", "Tom sabe que o erro foi dele, então liga para ela."], ["He tells her the truth and makes a promise.", "Ele conta a verdade e faz uma promessa."], ["They apologize to each other and forgive each other.", "Eles pedem desculpas um ao outro e se perdoam."], ["Now they make up, and they trust each other again.", "Agora eles fazem as pazes e confiam um no outro de novo."]], [["Why didn't you call me on my birthday?", "Por que você não me ligou no meu aniversário?"], ["I'm sorry. I forgot, and it was my mistake.", "Desculpa. Eu esqueci, e o erro foi meu."], ["We never argue, Tom. I'm really upset.", "A gente nunca briga, Tom. Estou muito chateada."], ["I don't blame you. I want to make up today.", "Não te culpo. Quero fazer as pazes hoje."], ["Do you promise to remember next year?", "Você promete lembrar no ano que vem?"], ["I promise. We always help each other, right?", "Prometo. A gente sempre se ajuda, né?"], ["Yes, we do. Tell me the truth, and I'll forgive you.", "Sim. Me diga a verdade, e eu te perdoo."], ["Thank you! Let's have a small party at the venue tonight.", "Obrigado! Vamos fazer uma festinha no salão hoje à noite."], ["Good idea. I'll check the guest list and send the RSVP.", "Boa ideia. Vou ver a lista de convidados e mandar a confirmação."], ["Perfect. And we can talk to each other all night.", "Ótimo. E podemos conversar a noite toda."]], ["/r/ em argue e hug", "No inglês americano, o r se faz com a língua puxada para trás, sem encostar no céu da boca e sem vibrar como o 'rr' de 'carro'. Em argue, o r vem depois da vogal: 'ARR-guiu'.", ["argue", "apologize"]], ["Mia and Tom talk to ___ every day.", "each other", "each others", "Mia e Tom conversam um com o outro todo dia.", "Each other é invariável; não leva -s."], [["They apologize to each other and forgive each other.", "Eles pedem desculpas um ao outro e se perdoam."], ["I promise. We always help each other, right?", "Prometo. A gente sempre se ajuda, né?"]], [{"t": "c", "q": "My sister and I hug ___ at the airport.", "o": ["each other", "each others", "other one"], "pt": "Minha irmã e eu nos abraçamos no aeroporto.", "why": "Each other mostra uma ação recíproca e nunca leva -s."}, {"t": "l", "say": "We always help each other.", "o": ["We always help each other.", "We always help each others.", "We always help other each."], "why": "A forma correta é each other, nessa ordem e sem -s."}, {"t": "b", "pt": "Eles se abraçam.", "w": ["They", "hug", "each", "other"]}, {"t": "b", "pt": "Nós sempre confiamos um no outro.", "w": ["We", "always", "trust", "each", "other"]}]];
