englishA2Plans[193]={"title": "Passeio em ônibus panorâmico", "file": "", "grammar": "Why don't we e How about + -ing", "goal": "Faça sugestões usando How about.", "words": [["aisle seat", "assento do corredor"], ["countryside", "interior"], ["snack bar", "lanchonete"], ["pull into", "chegar em"], ["sightseeing", "passeio turístico"], ["bumpy", "esburacado"], ["hiking", "caminhada na natureza"], ["bus tour", "passeio de ônibus"]]};
englishA2Content[193]=[[["Mia and Ben take a sightseeing bus in the city.", "Mia e Ben pegam um ônibus de passeio turístico na cidade."], ["Mia takes the aisle seat, and Ben sits by the window.", "Mia fica com o assento do corredor, e Ben senta perto da janela."], ["The bus goes under a big archway.", "O ônibus passa por baixo de um grande arco."], ["Soon the road is bumpy, and the countryside looks green.", "Logo a estrada fica esburacada, e o interior parece verde."], ["The scenery is beautiful, and Mia takes a lot of photos.", "A paisagem é linda, e Mia tira muitas fotos."], ["The bus will pull into a small town at noon.", "O ônibus vai chegar em uma cidadezinha ao meio-dia."]], [["How about getting a snack? There's a snack bar at the back.", "Que tal comer um lanche? Tem uma lanchonete no fundo."], ["Good idea. I'm hungry, but the road is so bumpy!", "Boa ideia. Estou com fome, mas a estrada está tão esburacada!"], ["True. Why don't we wait until we pull into the next town?", "É verdade. Por que não esperamos até chegar na próxima cidade?"], ["Okay. Look, there's an old monument near the lamppost. Can you see it?", "Certo. Olhe, tem um monumento antigo perto do poste de luz. Você consegue ver?"], ["Yes! Wow, it's so tall. How about taking a photo from here?", "Sim! Nossa, é tão alto. Que tal tirar uma foto daqui?"], ["Sure, I'll take it with my phone. Tomorrow we can go hiking in the hills.", "Claro, eu tiro com meu celular. Amanhã podemos fazer uma caminhada nas colinas."], ["Nice! Is it far from the city? I don't have much time.", "Legal! Fica longe da cidade? Não tenho muito tempo."], ["No, it's only an hour away. I checked the map this morning.", "Não, fica a só uma hora daqui. Eu olhei o mapa hoje de manhã."]], ["/aʊ/ em countryside e how", "O som /aʊ/ de how e countryside começa com a boca aberta, como o 'a' de 'casa', e termina com os lábios fechando em 'u'. Pense em 'á-u' bem ligado, como em 'cauda'.", ["countryside", "how"]], ["Why don't we ___ to the snack bar?", "go", "going", "Por que não vamos até a lanchonete?", "Depois de Why don't we usamos o verbo na forma base: go."], [["How about getting a snack? There's a snack bar at the back.", "Que tal comer um lanche? Tem uma lanchonete no fundo."], ["True. Why don't we wait until we pull into the next town?", "É verdade. Por que não esperamos até chegar na próxima cidade?"]], [{"t": "c", "q": "How about ___ a photo of the monument?", "o": ["taking", "take", "to take"], "pt": "Que tal tirar uma foto do monumento?", "why": "Depois de How about usamos o verbo com -ing."}, {"t": "l", "say": "Why don't we sit in the aisle seat?", "o": ["Why don't we sit in the aisle seat?", "Why we don't sit in the aisle seat?", "Why don't we sat in the aisle seat?"], "why": "A ordem é Why don't we + verbo base."}, {"t": "b", "pt": "Que tal tirar uma foto?", "w": ["How", "about", "taking", "a", "photo"]}, {"t": "b", "pt": "Por que não esperamos aqui?", "w": ["Why", "don't", "we", "wait", "here"]}]];
