englishA2Plans[195]={"title": "Recados na secretária eletrônica", "file": "", "grammar": "Told e asked em discurso indireto", "goal": "Relate pedidos e perguntas usando told e asked.", "words": [["voicemail", "correio de voz"], ["beep", "bipe"], ["ringtone", "toque de celular"], ["hang up", "desligar"], ["ringing", "tocando"], ["caller", "quem liga"], ["urgent", "urgente"], ["missed call", "chamada perdida"]]};
englishA2Content[195]=[[["Tom plays his voicemail after work.", "Tom ouve o correio de voz depois do trabalho."], ["First he hears a beep, and then a short greeting.", "Primeiro ele ouve um bipe, e depois uma saudação curta."], ["The caller is Ana, and she sounds happy.", "Quem liga é a Ana, e ela parece feliz."], ["She asked if he could go to the countryside this weekend.", "Ela perguntou se ele podia ir para o interior neste fim de semana."], ["Then his ringtone starts, and the phone is ringing again.", "Então o toque do celular começa, e o telefone está tocando de novo."], ["Ana told him to call back fast, so he does not hang up.", "Ana disse a ele para ligar de volta rápido, então ele não desliga."]], [["Hi, Ana! Sorry, I missed your call. I heard your voicemail.", "Oi, Ana! Desculpe, perdi sua ligação. Ouvi seu correio de voz."], ["No problem. I told you to call me back, and I asked if you were free.", "Sem problema. Eu disse para você me ligar de volta e perguntei se você estava livre."], ["Yes, I'm free. Your message sounded urgent, so I called right away.", "Sim, estou livre. Sua mensagem pareceu urgente, então liguei na hora."], ["It's okay. Mia asked me to invite you to the countryside this weekend.", "Tudo bem. A Mia me pediu para convidar você para o interior neste fim de semana."], ["Sounds fun! Is there any gossip? My inbox has no news.", "Parece divertido! Tem alguma fofoca? Minha caixa de entrada não tem novidades."], ["Yes. She told me that Ben got a promotion! But don't tell anyone.", "Sim. Ela me disse que o Ben ganhou uma promoção! Mas não conte a ninguém."], ["Wow, that's great news. I won't say a word.", "Uau, que ótima notícia. Não vou dizer nada."], ["Perfect. I have to hang up now. See you on Saturday!", "Perfeito. Preciso desligar agora. Até sábado!"]], ["/l/ em voicemail e ringtone", "O /l/ de voicemail e ringtone pede a ponta da língua encostada atrás dos dentes de cima. No fim da palavra (mail), o 'l' fica mais escuro, como o 'u' do português do Brasil em 'mal'.", ["voicemail", "ringtone"]], ["Ana ___ me to call back.", "told", "said", "Ana me disse para ligar de volta.", "Depois de me + to + verbo usamos told (told me to call); said não funciona assim."], [["No problem. I told you to call me back, and I asked if you were free.", "Sem problema. Eu disse para você me ligar de volta e perguntei se você estava livre."], ["It's okay. Mia asked me to invite you to the countryside this weekend.", "Tudo bem. A Mia me pediu para convidar você para o interior neste fim de semana."]], [{"t": "c", "q": "Ben ___ me if I was free.", "o": ["asked", "told", "said"], "pt": "Ben me perguntou se eu estava livre.", "why": "Para relatar uma pergunta com if usamos asked."}, {"t": "l", "say": "She asked me to call back.", "o": ["She asked me to call back.", "She asked me call back.", "She asks me to call back."], "why": "A estrutura é asked + me + to + verbo, e a frase está no passado."}, {"t": "b", "pt": "Ana me disse para ligar de volta.", "w": ["Ana", "told", "me", "to", "call", "back"]}, {"t": "b", "pt": "Ele perguntou se eu estava livre.", "w": ["He", "asked", "if", "I", "was", "free"]}]];
