englishA2ExtraWordExamples[200]={"cozy": ["My bed is cozy in winter.", "Minha cama é aconchegante no inverno."], "bedtime story": ["I read a bedtime story before sleeping.", "Leio uma história de dormir antes de dormir."], "turn off": ["Turn off the light after brushing your teeth.", "Desligue a luz depois de escovar os dentes."], "sweet dreams": ["She says sweet dreams after reading to him.", "Ela diz bons sonhos depois de ler para ele."]};
englishA2Plans[201]={"title": "Sabores em um mercado asiático", "file": "", "grammar": "Look, sound, taste e smell + adjetivo", "goal": "Descreva sentidos usando look e smell.", "words": [["spice", "tempero"], ["noodle", "macarrão"], ["seaweed snack", "petisco de alga"], ["mouthwatering", "de dar água na boca"], ["crunchy", "crocante"], ["salty", "salgado"], ["broth", "caldo"], ["bitter", "amargo"]]};
englishA2Content[201]=[[["Mia and Tom walk through a busy Asian market.", "Mia e Tom andam por um mercado asiático movimentado."], ["The noodle shop smells wonderful, and the steam looks hot.", "A loja de macarrão tem um cheiro maravilhoso, e o vapor parece quente."], ["The seaweed snack tastes salty and crunchy.", "O petisco de alga tem gosto salgado e é crocante."], ["The broth looks cloudy, but it tastes great.", "O caldo parece turvo, mas tem um gosto ótimo."], ["Every spice smells strong, and the soup looks mouthwatering.", "Todo tempero tem cheiro forte, e a sopa parece de dar água na boca."], ["Tom thinks a warm bowl of soup is good for the soul.", "Tom acha que uma tigela de sopa quente faz bem para a alma."]], [["Wow, this market smells amazing! What do you want to try first?", "Uau, este mercado tem um cheiro incrível! O que você quer provar primeiro?"], ["That noodle shop. The steam looks great, and I'm starving.", "Aquela loja de macarrão. O vapor parece ótimo, e estou morrendo de fome."], ["Okay. That sauce looks really hot, though. Do you like spicy food?", "Certo. Mas aquele molho parece muito forte. Você gosta de comida picante?"], ["A little. Cooking is my hobby, but strong garlic and spices are hard for me.", "Um pouco. Cozinhar é meu hobby, mas alho e temperos fortes são difíceis para mim."], ["Then let's get a small bowl and share it, okay?", "Então vamos pegar uma tigela pequena e dividir, certo?"], ["Sure. Hey, try this seaweed snack. It tastes salty, not bitter!", "Claro. Ei, experimente este petisco de alga. Tem gosto salgado, não amargo!"], ["Really? It's crunchy, too. I'll buy two bags for movie night in my spare time.", "Sério? É crocante também. Vou comprar dois pacotes para a noite de filme no meu tempo livre."], ["Great idea. We can eat everything at home in our pajamas.", "Ótima ideia. Podemos comer tudo em casa de pijama."]], ["/oʊ/ em noodle e soul", "O /oʊ/ de noodle e soul começa com a boca em 'ô' e termina fechando os lábios num 'u' leve; é um ditongo, não um 'o' puro como em 'sol'.", ["noodle", "soul"]], ["The broth looks cloudy, but it ___ great.", "tastes", "tastes like", "O caldo parece turvo, mas tem um gosto ótimo.", "Depois de taste vem um adjetivo direto (tastes sweet); like só entra antes de substantivo."], [["The seaweed snack tastes salty and crunchy.", "O petisco de alga tem gosto salgado e é crocante."], ["The broth looks cloudy, but it tastes great.", "O caldo parece turvo, mas tem um gosto ótimo."]], [{"t": "c", "q": "This market ___ amazing!", "o": ["smells", "smells like", "smell"], "pt": "Este mercado tem um cheiro incrível!", "why": "This market é singular, então smells; depois vem o adjetivo amazing, sem like."}, {"t": "l", "say": "The seaweed snack tastes salty and crunchy.", "o": ["The seaweed snack tastes salty and crunchy.", "The seaweed snack tastes sweet and crunchy.", "The seaweed snack smells salty and crunchy."], "why": "A frase ouvida diz tastes salty and crunchy."}, {"t": "b", "pt": "Essa sopa tem cheiro delicioso.", "w": ["This", "soup", "smells", "delicious"]}, {"t": "b", "pt": "O molho parece muito quente.", "w": ["The", "sauce", "looks", "really", "hot"]}]];
